-- ----------------------------
-- Table structure for bill_remittanceapplication
-- ----------------------------
DROP TABLE IF EXISTS `bill_remittanceapplication`;
CREATE TABLE `bill_remittanceapplication`  (
  `id` int(11) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '广宣费报销ID',
  `bill_sn` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '审批编号',
  `dept_id` int(11) NOT NULL COMMENT '创建人部门',
  `total_money` decimal(11, 2) NOT NULL COMMENT '总金额',
  `approve_date` date NOT NULL COMMENT '支付日期',
  `use_date` date NOT NULL COMMENT '预计报销日期',
  `nashui_number` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '收款单位/人',
  `bank` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '开户银行',
  `bank_account` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '银行账号',
  `process_status` tinyint(1) NOT NULL COMMENT '审核状态：0未提交，1未审批，2审批通过，3已撤消，4审批拒绝',
  `create_time` int(10) NULL DEFAULT NULL COMMENT '创建时间',
  `create_user_id` int(11) NULL DEFAULT NULL COMMENT '创建人',
  `update_time` int(11) NULL DEFAULT NULL COMMENT '更新时间',
  `update_user_id` int(11) NULL DEFAULT NULL COMMENT '更新人',
  `copy` tinyint(1) NULL DEFAULT 0 COMMENT '是否是复制而来的单据0否 1是',
  `bill_number` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL,
  `address` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL,
  `company_telephone_no` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL,
  `send_type_id` int(1) NULL DEFAULT NULL,
  `type_id` int(1) NULL DEFAULT NULL,
  `fapiao_no` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL,
  `fapiao_money` decimal(11, 2) NULL DEFAULT NULL,
  `cus_moblie` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL,
  `bill_type` int(2) NOT NULL,
  `remark` text CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL,
  `caiwu_remark` text CHARACTER SET utf8 COLLATE utf8_general_ci NULL,
  `caiwu_remark1` text CHARACTER SET utf8 COLLATE utf8_general_ci NULL,
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1618 CHARACTER SET = utf8 COLLATE = utf8_general_ci ROW_FORMAT = Dynamic;

