-- ----------------------------
-- Table structure for brand
-- ----------------------------
DROP TABLE IF EXISTS `brand`;
CREATE TABLE `brand`  (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `company_id` int(11) NOT NULL,
  `factory_id` int(11) NULL DEFAULT NULL,
  `name` varchar(100) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL,
  `responsible_person_id` int(11) UNSIGNED NOT NULL DEFAULT 0 COMMENT '采购专员',
  `dept_id` int(11) UNSIGNED NULL DEFAULT 0 COMMENT '所属店面',
  `dis` float(3, 2) UNSIGNED NULL DEFAULT 1.00 COMMENT '销售折扣',
  `quotation` float(3, 2) NULL DEFAULT NULL COMMENT '报价细数',
  `common_flg` tinyint(3) NOT NULL DEFAULT 0 COMMENT '常用标志',
  `all-staff_sales` tinyint(1) UNSIGNED NULL DEFAULT 1 COMMENT '全员销售标识',
  `is_ss_flg` int(2) NULL DEFAULT 0,
  `is_del` tinyint(1) UNSIGNED NULL DEFAULT 0 COMMENT '删除标识',
  `create_user_id` int(11) NULL DEFAULT NULL COMMENT '创建者ID',
  `create_date` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `update_user_id` int(11) NULL DEFAULT NULL COMMENT '更新者ID',
  `update_date` datetime NULL DEFAULT NULL COMMENT '更新时间',
  `sm_dis` float(3, 2) NOT NULL DEFAULT 1.00,
  `ssm_dis` float(3, 2) NOT NULL DEFAULT 1.00,
  `bm_dis` float(3, 2) NOT NULL DEFAULT 1.00,
  `sd_dis` float(3, 2) NOT NULL DEFAULT 1.00,
  `logo` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL,
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `brand_search_index`(`id`, `name`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1109 CHARACTER SET = utf8 COLLATE = utf8_general_ci ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for brand_channel
-- ----------------------------
