-- ----------------------------
-- Table structure for brand_inquiry
-- ----------------------------
DROP TABLE IF EXISTS `brand_inquiry`;
CREATE TABLE `brand_inquiry`  (
  `id` int(11) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `brand_id` int(11) NOT NULL COMMENT '品牌ID',
  `channel_id` int(11) NOT NULL COMMENT '渠道ID',
  `goods_name` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '商品名称',
  `goods_image` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '商品图片',
  `cost_price` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '成本价',
  `retail_price` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '零售价',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `create_user` int(11) NULL DEFAULT NULL COMMENT '创建人',
  `update_user` int(11) NULL DEFAULT NULL COMMENT '更新人',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_brand_id`(`brand_id`) USING BTREE,
  INDEX `idx_channel_id`(`channel_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 10 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '品牌询价表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for brand_point
-- ----------------------------
DROP TABLE IF EXISTS `brand_point`;
CREATE TABLE `brand_point`  (
  `id` int(11) UNSIGNED NOT NULL AUTO_INCREMENT,
  `factory_id` int(11) NOT NULL COMMENT '供应商ID',
  `brand_id` int(11) NOT NULL COMMENT '品牌ID',
  `brand_name` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '品牌名',
  `dis` float(3, 2) NOT NULL COMMENT '折扣',
