DROP TABLE IF EXISTS `cash_bank_history`;
CREATE TABLE `cash_bank_history`  (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `bills_type` tinyint(1) NOT NULL COMMENT '单据类型：1、销售单，2、退货单，3、采购单，4、采购退货单，5、一般费用单，6，付款单',
  `cash_flow_subject_id` int(11) NOT NULL COMMENT '现金流科目',
  `bills_no` varchar(100) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '单据编号',
  `bills_id` int(11) NOT NULL COMMENT '单据ID',
  `dept_id` int(11) NULL DEFAULT NULL COMMENT '部门ID',
  `create_date` date NULL DEFAULT NULL,
  `emp_id` int(11) NOT NULL COMMENT '职员ID',
  `emp_name` varchar(100) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '职员全名',
  `subject_id` int(11) NOT NULL COMMENT '科目id',
  `subject_name` varchar(100) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '科目全名',
  `unit_type` tinyint(1) NOT NULL COMMENT '单位类型:1、客户，2、供应商',
  `unit_id` int(11) NOT NULL COMMENT '单位ID',
  `unit_name` varchar(100) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '单位全名',
  `inc_amount` decimal(35, 20) NULL DEFAULT NULL,
  `dec_amount` decimal(35, 20) NULL DEFAULT NULL,
  `balance` decimal(35, 20) NULL DEFAULT NULL COMMENT '余额',
  `remark` text CHARACTER SET utf8 COLLATE utf8_general_ci NULL COMMENT '摘要',
  `create_user_id` int(11) NULL DEFAULT NULL,
  `create_time` int(10) NULL DEFAULT NULL,
  `update_time` int(10) NULL DEFAULT NULL,
  `fee_type` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL,
  `fee_id` int(10) NOT NULL,
  `total_bill_sn` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL,
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `cash_bank_history_search_index`(`id`, `cash_flow_subject_id`, `bills_no`, `bills_id`, `dept_id`, `emp_id`, `subject_id`, `unit_id`, `fee_id`, `total_bill_sn`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 188878 CHARACTER SET = utf8 COLLATE = utf8_general_ci ROW_FORMAT = Dynamic;

