) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8 COLLATE = utf8_general_ci ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for current_account
-- ----------------------------
DROP TABLE IF EXISTS `current_account`;
CREATE TABLE `current_account`  (
  `id` int(11) NOT NULL AUTO_INCREMENT COMMENT '单位编号',
  `pid` int(11) NOT NULL DEFAULT 0,
  `code` varchar(100) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '费用类型',
  `name` varchar(100) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '单位全名',
  `address` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '单位地址',
  `telephone` varchar(20) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '单位电话',
  `email` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '电子邮件',
  `linkman` varchar(100) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '联系人',
  `phone` varchar(100) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '联系电话',
  `bank` varchar(100) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '开户银行',
  `bank_code` varchar(100) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '银行卡号',
  `initial_receivables` decimal(11, 2) NULL DEFAULT 0.00 COMMENT '初期应收款',
  `initial_payable` decimal(11, 2) NULL DEFAULT 0.00 COMMENT '初期应付款',
  `initial_advances_received` decimal(11, 2) NULL DEFAULT 0.00 COMMENT '初期预收款',
  `initial_advances_payment` decimal(11, 2) NULL DEFAULT 0.00 COMMENT '初期预付款',
  `duty_paragraph` varchar(100) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '税号',
  `receivables_max` decimal(11, 2) NULL DEFAULT 0.00 COMMENT '应收款上限',
  `payable_max` decimal(11, 2) NULL DEFAULT 0.00 COMMENT '应付款上限',
  `replacement_period` int(10) NULL DEFAULT 0 COMMENT '换货期限（天）',
  `replacement_proportion` float(3, 2) NULL DEFAULT 0.00 COMMENT '换货比例（100%）',
  `settlement_period` int(10) NULL DEFAULT 0 COMMENT '结算期限（天）',
  `cumulative_receivables` decimal(11, 2) NULL DEFAULT NULL COMMENT '累计应收',
  `cumulative_payable` decimal(11, 2) NULL DEFAULT 0.00 COMMENT '累计应付',
  `cumulative_received` decimal(11, 2) NULL DEFAULT NULL COMMENT '累计预收',
  `cumulative_payment` decimal(11, 2) NULL DEFAULT NULL COMMENT '累计预付',
  `etc` int(11) NULL DEFAULT NULL COMMENT '默认经手人ID',
  `remark` text CHARACTER SET utf8 COLLATE utf8_general_ci NULL COMMENT '备注',
  `create_user_id` int(11) NULL DEFAULT NULL COMMENT '创建人',
  `create_time` int(10) NULL DEFAULT NULL,
  `update_user_id` int(11) NULL DEFAULT NULL COMMENT '更新人',
  `update_time` int(10) NULL DEFAULT NULL COMMENT '更新时间',
  `account_set` int(11) NULL DEFAULT NULL COMMENT '所属账套',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `current_account_search_index`(`id`, `pid`, `code`, `telephone`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1014 CHARACTER SET = utf8 COLLATE = utf8_general_ci ROW_FORMAT = Dynamic;

