  `current_id` int(11) NOT NULL COMMENT '支付银行',
  `current_name` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL,
  `amount` decimal(11, 2) NOT NULL COMMENT '金额',
  `abstract` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '摘要',
  `status` tinyint(1) NOT NULL DEFAULT 1 COMMENT '状态：1、草稿，2、单据',
