  PRIMARY KEY (`id`) USING BTREE,
  INDEX `subject_id`(`subject_id`) USING BTREE,
  INDEX `dept_id`(`dept_id`) USING BTREE,
  INDEX `current_cost_search_index`(`id`, `bill_sn`, `current_id`, `fee_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 8335 CHARACTER SET = utf8 COLLATE = utf8_general_ci ROW_FORMAT = Dynamic;

