-- ----------------------------
-- Table structure for customer
-- ----------------------------
DROP TABLE IF EXISTS `customer`;
CREATE TABLE `customer`  (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '客户id',
  `dept_id` int(11) NULL DEFAULT NULL,
  `user_id` bigint(20) NOT NULL DEFAULT 0 COMMENT '用户id',
  `old_customer_id` bigint(20) NULL DEFAULT NULL COMMENT '旧客户ID',
  `customer_name` varchar(24) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '客户姓名',
  `customer_sex` tinyint(3) NULL DEFAULT NULL COMMENT '客户性别(1:先生、2:女士)',
  `customer_birthday` date NULL DEFAULT NULL COMMENT '客户生日',
  `customer_age_group` tinyint(3) NULL DEFAULT NULL COMMENT '客户年龄段(1:30岁以下、2:30岁至39岁、3:40岁至49岁、4:50岁以上)',
  `zipcode` varchar(20) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '邮政编码',
  `postal_address` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '邮寄地址',
  `customer_first_contact` varchar(20) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '联系方式1',
  `customer_second_contact` varchar(20) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '联系方式2',
  `customer_wechat` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '客户微信',
  `customer_email` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '客户电子邮箱',
  `introduce_customer_id` bigint(20) NULL DEFAULT NULL COMMENT '转介绍顾客id',
  `other_contact_name` varchar(24) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '其他联系人姓名',
  `other_contact_sex` tinyint(3) NULL DEFAULT NULL COMMENT '其他联系人性别(1:先生、2:女士)',
  `other_contact_mobile` varchar(11) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '其他联系人手机号',
  `other_contact_wechat` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '其他联系人微信',
  `other_contact_email` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '其他联系人电子邮箱',
  `customer_relation` varchar(24) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '与客户的关系',
  `remarks` text CHARACTER SET utf8 COLLATE utf8_general_ci NULL COMMENT '其它备注内容',
  `level` enum('A','B','C','D','L') CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT 'C' COMMENT '需求级别(A:整组购买可家访、B:整组购买不可家访、C:零星购买、D:已下单、L:丢单)',
  `up_level` int(10) NULL DEFAULT NULL COMMENT '转重点客户时间',
  `plevel` tinyint(3) NULL DEFAULT 3 COMMENT '下单金额判断',
  `channel_id` bigint(20) NULL DEFAULT NULL COMMENT '进店渠道',
  `create_user_id` bigint(20) NULL DEFAULT NULL COMMENT '创建人id',
  `create_time` int(10) NULL DEFAULT NULL COMMENT '创建时间',
  `actual_sales` decimal(11, 2) NULL DEFAULT 0.00,
  `payment` decimal(11, 2) NULL DEFAULT 0.00,
  `available_balance` decimal(11, 2) NULL DEFAULT 0.00,
  `desginer_id` int(11) NULL DEFAULT NULL COMMENT '设计师id',
  `xiadan_money` int(11) NULL DEFAULT NULL,
  `house_group` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL,
  `jiafang_time` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL,
  `yixiang_production` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL,
  `yujixiadan_time` date NULL DEFAULT NULL,
  `create_user_id_copy` bigint(20) NULL DEFAULT NULL,
  `loupan_id` int(11) NULL DEFAULT NULL,
  `yiyelianmeng_id` int(11) NULL DEFAULT NULL,
  `customer_referrals_id` int(11) NULL DEFAULT NULL COMMENT '设计师id',
  `from_emp_id` int(11) NULL DEFAULT NULL,
  `from_emp_time` int(11) NULL DEFAULT NULL,
  `copy_emp_id` int(11) NULL DEFAULT NULL,
  `copy_emp_time` int(11) NULL DEFAULT NULL,
  `baili_flg` tinyint(1) NULL DEFAULT 0 COMMENT '1 五一店 2独立店',
  `from_dept_id` int(11) NULL DEFAULT NULL,
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `customer_unique`(`customer_first_contact`, `customer_wechat`, `create_user_id`) USING BTREE,
  INDEX `customer_search_index`(`id`, `dept_id`, `customer_name`, `customer_first_contact`, `customer_wechat`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 96914 CHARACTER SET = utf8 COLLATE = utf8_general_ci ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for customer_address
-- ----------------------------
DROP TABLE IF EXISTS `customer_address`;
CREATE TABLE `customer_address`  (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `customer_id` int(11) NOT NULL,
  `name` varchar(100) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL,
  `contact` varchar(100) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL,
  `buildingId` bigint(20) NULL DEFAULT NULL COMMENT '楼盘ID',
  `province_code` varchar(6) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '省 编号',
  `city_code` varchar(6) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '市 编号',
  `area_code` varchar(6) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '区 编号',
  `address` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL,
  `type` tinyint(3) NULL DEFAULT 1 COMMENT '类型:1 高层 2 多层 3 越层 4 别墅',
  `progress` tinyint(3) NULL DEFAULT 1 COMMENT '装修进度:1 未装修 2 装修中 3 已装修',
  `area` int(11) NULL DEFAULT NULL,
  `create_time` int(11) NULL DEFAULT NULL,
  `create_user_id` int(11) NULL DEFAULT NULL,
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 28177 CHARACTER SET = utf8 COLLATE = utf8_general_ci ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for customer_address_temp
-- ----------------------------
DROP TABLE IF EXISTS `customer_address_temp`;
CREATE TABLE `customer_address_temp`  (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `customer_id` int(11) NOT NULL COMMENT '客户ID',
  `name` varchar(100) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '房屋联系人姓名',
  `contact` varchar(100) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '联系电话',
  `buildingId` bigint(20) NULL DEFAULT NULL COMMENT '楼盘ID',
  `address` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '详细地址',
  `type` tinyint(3) NULL DEFAULT 1 COMMENT '类型:1 平层 2 越层 3 别墅',
  `progress` tinyint(3) NULL DEFAULT 1 COMMENT '装修进度:1 未装修 2 装修中 3 已装修',
  `area` int(11) NULL DEFAULT NULL COMMENT '面积',
  `create_time` int(11) NULL DEFAULT NULL COMMENT '创建时间',
  `create_user_id` int(11) NULL DEFAULT NULL COMMENT '创建人ID',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 387 CHARACTER SET = utf8 COLLATE = utf8_general_ci ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for customer_bak
-- ----------------------------
DROP TABLE IF EXISTS `customer_bak`;
CREATE TABLE `customer_bak`  (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `company_id` int(11) NOT NULL,
  `dept_id` int(11) NULL DEFAULT NULL,
  `customer_class` tinyint(3) NOT NULL DEFAULT 1 COMMENT '顾客类别：1 意向，2 下单，3 丢单，4 重点',
