  `role` enum('审批人','抄送人') CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '审批人' COMMENT '角色：审批人，抄送人',
  `create_time` int(11) NULL DEFAULT NULL COMMENT '创建时间',
  `create_user_id` int(11) NULL DEFAULT NULL COMMENT '创建人',
  `update_time` int(11) NULL DEFAULT NULL COMMENT '更新时间',
  `update_user_id` int(11) NULL DEFAULT NULL COMMENT '更新人',
  `base` int(2) NULL DEFAULT 0 COMMENT '基本审批人',
  `delivery_settlement_id` int(11) NULL DEFAULT NULL,
  `list` text CHARACTER SET utf8 COLLATE utf8_general_ci NULL,
  `wx` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL,
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1045 CHARACTER SET = utf8 COLLATE = utf8_general_ci ROW_FORMAT = Dynamic;

-- ----------------------------
