-- ----------------------------
-- Table structure for emp
-- ----------------------------
DROP TABLE IF EXISTS `emp`;
CREATE TABLE `emp`  (
  `id` int(11) UNSIGNED NOT NULL AUTO_INCREMENT,
  `employee_id` int(11) NULL DEFAULT NULL COMMENT '正式员工id',
  `name` varchar(100) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '中文姓名',
  `gender` tinyint(1) UNSIGNED NOT NULL DEFAULT 1 COMMENT '性别 1:男,2:女',
  `identity_card` varchar(20) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '身份证',
  `contact_number` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '联络电话',
  `qualification` varchar(60) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '最终学历',
  `birthday` date NULL DEFAULT NULL COMMENT '出生年月',
  `age` int(3) NULL DEFAULT NULL COMMENT '年龄',
  `address` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '居住地址',
  `census_register` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '户籍地址',
  `marital_status` tinyint(1) NULL DEFAULT NULL COMMENT '婚姻状况 1:未婚 2:已婚 3:离异 4:丧偶',
  `photo` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '照片',
  `dept_id` int(11) NOT NULL COMMENT '入职(门店/部门)',
  `join_date` date NOT NULL COMMENT '入职日期',
  `initial_position` int(11) NOT NULL COMMENT '入职岗位',
  `position_id` int(11) NOT NULL,
  `emp_status` tinyint(1) UNSIGNED NOT NULL DEFAULT 1 COMMENT '职员状态 1:未审核、2:待开通、3:正常、4:禁用、5:离职',
  `create_user_id` int(11) NULL DEFAULT NULL COMMENT '创建者id',
  `create_time` int(10) NULL DEFAULT NULL COMMENT '创建时间',
  `update_user_id` int(11) NULL DEFAULT NULL COMMENT '更新者id',
  `update_time` int(10) NULL DEFAULT NULL COMMENT '更新时间',
  `to_report` int(11) NULL DEFAULT NULL COMMENT '上级',
  `del_flg` tinyint(1) UNSIGNED NULL DEFAULT 0 COMMENT '删除标识',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 199 CHARACTER SET = utf8 COLLATE = utf8_general_ci ROW_FORMAT = Dynamic;

