  `id` int(11) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '表ID',
  `dept_id` int(11) UNSIGNED NOT NULL COMMENT '部门ID',
  `dept_name` varchar(100) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '部门名称',
  `emp_id` int(11) NOT NULL COMMENT '员工ID',
  `emp_name` varchar(100) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '员工姓名',
  `wage_date` varchar(10) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '工资发放时间（年/月）',
  `sales_amount` decimal(11, 2) NOT NULL DEFAULT 0.00 COMMENT '销售额',
  `full_amount` decimal(11, 2) NOT NULL DEFAULT 0.00 COMMENT '全款额',
  `mattress_amount` int(11) NOT NULL DEFAULT 0 COMMENT '床垫数量',
  `ornament_amount` decimal(11, 2) NOT NULL DEFAULT 0.00 COMMENT '软件饰品',
  `team_sales_amount` decimal(11, 2) NOT NULL DEFAULT 0.00 COMMENT '团队销售额',
  `team_full_amount` decimal(11, 2) NOT NULL DEFAULT 0.00 COMMENT '团队全款额',
  `increase_amount` decimal(11, 2) NOT NULL DEFAULT 0.00 COMMENT '递增金额',
  `current_increase_dis` float(4, 3) NOT NULL DEFAULT 0.000 COMMENT '当前递增提点',
  `full_amount_award` decimal(11, 2) NOT NULL DEFAULT 0.00 COMMENT '全款奖',
  `performance_award` decimal(11, 2) NOT NULL DEFAULT 0.00 COMMENT '绩效奖励',
  `sales_amount_award` decimal(11, 2) NOT NULL DEFAULT 0.00 COMMENT '个人奖',
  `team_sales_amount_award` decimal(11, 2) NOT NULL DEFAULT 0.00 COMMENT '团队奖',
  `basic_wage` decimal(11, 2) NOT NULL DEFAULT 0.00 COMMENT '底薪',
  `deduct_absenteeism` decimal(11, 2) NOT NULL DEFAULT 0.00 COMMENT '减缺勤',
  `deduct_social_insurance` decimal(11, 2) NOT NULL DEFAULT 0.00 COMMENT '减社保',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 228 CHARACTER SET = utf8 COLLATE = utf8_general_ci ROW_FORMAT = Dynamic;

