-- ----------------------------
-- Table structure for external_consultant
-- ----------------------------
DROP TABLE IF EXISTS `external_consultant`;
CREATE TABLE `external_consultant`  (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `bill_sn` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '申请单号',
  `start_date` date NOT NULL COMMENT '开始日期',
  `end_date` date NOT NULL COMMENT '结束日期',
  `estimated_cost` decimal(10, 2) NOT NULL COMMENT '预估费用',
  `work_content` text CHARACTER SET utf8 COLLATE utf8_general_ci NULL COMMENT '工作内容',
  `apply_reason` text CHARACTER SET utf8 COLLATE utf8_general_ci NULL COMMENT '申请理由',
  `process_status` tinyint(1) NOT NULL DEFAULT 0 COMMENT '审批状态：0草稿 1审批中 2已通过 3已拒绝',
  `current_approver_id` int(11) NULL DEFAULT NULL COMMENT '当前审批人ID',
  `current_approver_name` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '当前审批人姓名',
  `dept_id` int(11) NOT NULL COMMENT '申请部门',
  `create_user_id` int(11) NOT NULL COMMENT '创建人ID',
  `create_user_name` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '创建人姓名',
  `create_time` int(11) NOT NULL COMMENT '创建时间',
  `update_user_id` int(11) NULL DEFAULT NULL COMMENT '更新人ID',
  `update_time` int(11) NULL DEFAULT NULL COMMENT '更新时间',
  `submit_time` int(11) NULL DEFAULT NULL COMMENT '提交时间',
  `approve_time` int(11) NULL DEFAULT NULL COMMENT '审批通过时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_application_sn`(`bill_sn`) USING BTREE,
  INDEX `idx_create_user`(`create_user_id`) USING BTREE,
  INDEX `idx_process_status`(`process_status`) USING BTREE,
  INDEX `idx_current_approver`(`current_approver_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 3 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '外顾人员申请表' ROW_FORMAT = Dynamic;

