-- ----------------------------
-- Table structure for factory_activity
-- ----------------------------
DROP TABLE IF EXISTS `factory_activity`;
CREATE TABLE `factory_activity`  (
  `id` int(11) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '广宣费报销ID',
