  `content` text CHARACTER SET utf8 COLLATE utf8_general_ci NULL COMMENT '内容',
  `confirm` varchar(100) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT '' COMMENT '裁决数据',
  `confirm_name` text CHARACTER SET utf8 COLLATE utf8_general_ci NULL COMMENT '裁决显示内容',
