  `consult_name` text CHARACTER SET utf8 COLLATE utf8_general_ci NULL COMMENT '协商显示内容',
  `refer` varchar(100) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT '' COMMENT '抄送数据',
  `refer_name` text CHARACTER SET utf8 COLLATE utf8_general_ci NULL COMMENT '抄送显示内容',
  `create_time` int(11) UNSIGNED NULL DEFAULT 0 COMMENT '创建时间',
