  `is_del` int(2) NULL DEFAULT 0 COMMENT '是否删除标志0：否 1：是',
  `account_set` int(11) NOT NULL,
  `fee_type` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL,
