-- ----------------------------
-- Table structure for gongtong
-- ----------------------------
DROP TABLE IF EXISTS `gongtong`;
CREATE TABLE `gongtong`  (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `start_time` datetime NULL DEFAULT NULL COMMENT '开始时间',
  `predict_time` datetime NULL DEFAULT NULL COMMENT '预计完成时间',
