-- ----------------------------
-- Table structure for goods
-- ----------------------------
DROP TABLE IF EXISTS `goods`;
CREATE TABLE `goods`  (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `old_id` int(11) NULL DEFAULT NULL,
  `company_id` int(11) NULL DEFAULT 3 COMMENT '所属公司',
  `factory_id` int(11) NULL DEFAULT 0 COMMENT '供应商',
  `brand_id` int(11) NULL DEFAULT 0 COMMENT '品牌',
  `gjp_code` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '管家婆编号',
  `gjp_name` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '管家婆商品名',
  `goods_cotegory_id` int(11) NULL DEFAULT NULL COMMENT '系列',
  `goods_class` enum('其它','儿童房','书房','客厅','餐厅','卧房','卧室') CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT '卧房' COMMENT '功能',
  `goods_no` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '编号',
  `name` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '名称',
  `size` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT '' COMMENT '规格',
  `material` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT '' COMMENT '材质',
  `fabric` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT '' COMMENT '面料',
  `painting` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT '' COMMENT '涂装',
  `gjp_name_dl` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '管家婆编号(大连)作废',
  `gjp_name_sy` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '管家婆编号(沈阳)作废',
  `gjp_name_sjz` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '管家婆编号(石家庄)作废',
  `class` enum('家具','床垫','水晶板','其它','饰品','布艺','地毯','电器','定制','快销品') CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT '家具' COMMENT '种类',
  `photo` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '主图片',
  `photo1` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '副图片',
  `cost_price` decimal(11, 3) NULL DEFAULT NULL COMMENT '成本',
  `cost_price_fujian` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '成本附件',
  `price` decimal(11, 3) NULL DEFAULT NULL COMMENT '销售价',
  `offprice` decimal(8, 3) NULL DEFAULT NULL COMMENT '作废',
  `discount` float(3, 2) NULL DEFAULT NULL COMMENT '折扣作废',
  `unit` varchar(20) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '单位',
  `unit_quantity` varchar(10) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '作废',
  `fragile` enum('0','1') CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT '0' COMMENT '作废',
  `stop` tinyint(3) NULL DEFAULT 0 COMMENT '停产标识',
  `change` enum('0','1') CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT '0' COMMENT '改制标识作废',
  `show` enum('0','1') CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '1' COMMENT '显示标识',
  `status` enum('通过','审核中','未审核','待审核') CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT '未审核' COMMENT '状态',
  `property` enum('正常','专供','改制','特价','珍品') CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT '正常' COMMENT '属性',
  `element` tinyint(4) NULL DEFAULT 0 COMMENT '组件标识',
  `series` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '系列',
  `fangshu` decimal(11, 2) NULL DEFAULT NULL COMMENT '体积',
  `barcode` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '条码',
  `spu_id` bigint(20) NULL DEFAULT NULL,
  `main_param` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL,
  `auxiliary_param` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL,
  `custom_note` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '定制描述',
  `custom_quantity` int(10) NULL DEFAULT NULL COMMENT '定制数量',
  `custom_img` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '定制图片',
  `sample_room` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '样板间说明',
  `origin` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '产地',
  `price_img` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '价签',
  `create_user_id` bigint(20) NULL DEFAULT NULL COMMENT '创建人',
  `create_time` int(10) NULL DEFAULT NULL COMMENT '创建时间',
  `update_user_id` bigint(20) NULL DEFAULT NULL COMMENT '更新人',
  `update_time` int(10) NULL DEFAULT NULL COMMENT '更新时间',
  `price_tag_flg` tinyint(1) NULL DEFAULT 0 COMMENT '0:待生成，1：正常，2：更新',
  `create_price_tag_time` int(10) NULL DEFAULT NULL COMMENT '价签生成时间',
  `update_price_tag_time` int(10) NULL DEFAULT NULL COMMENT '价签更新时间',
  `SKU_ID` bigint(20) NULL DEFAULT NULL,
  `SKU_No` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL,
  `SKU_Description` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL,
  `SKU_Remark` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL,
  `goods_name1` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '曾用名',
  `remark` text CHARACTER SET utf8 COLLATE utf8_general_ci NULL COMMENT '备注',
  `jsj_goods_id` int(11) NULL DEFAULT NULL COMMENT '布艺商品id',
  `unit_price` decimal(11, 2) NULL DEFAULT NULL COMMENT '最新采购价',
  `goods_level` int(10) NULL DEFAULT NULL COMMENT '商品级别',
  `ajmy_goods_id` int(11) NULL DEFAULT NULL,
  `colour` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL,
  `paint_type` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL,
  `technology` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL,
  `base_material` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL,
  `calculate_type` int(1) NULL DEFAULT NULL,
  `goods_cotegory_id1` int(11) NOT NULL COMMENT '主分类',
  `goods_cotegory_id2` int(11) NOT NULL COMMENT '子分类',
  `caigou_flg` int(1) NOT NULL DEFAULT 0,
  `caigou_flg_time` int(11) NOT NULL,
  `caiwu_flg` int(1) NOT NULL DEFAULT 0,
  `caiwu_flg_time` int(11) NOT NULL,
  `before_info` text CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '修改前的信息',
  `nickname` text CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '商品拟称',
  `page_view` int(11) NULL DEFAULT 0,
  `is_falling_flg` int(1) NULL DEFAULT 0,
  `warehouse_id` int(11) NULL DEFAULT NULL,
  `type1` int(2) NULL DEFAULT 1,
  `shuxing_list_info_id` int(11) NULL DEFAULT NULL,
  `is_col` int(2) NULL DEFAULT 1,
  `main_goods_id` int(11) NULL DEFAULT 0,
  `price1` decimal(11, 2) NULL DEFAULT NULL COMMENT '一级销售价',
  `price2` decimal(11, 2) NULL DEFAULT NULL COMMENT '二级销售价',
  `price3` decimal(11, 2) NULL DEFAULT NULL COMMENT '三级销售价',
  `goods_cotegory_id3` int(11) NULL DEFAULT NULL COMMENT '最末级类别',
  `factory_tegong` enum('0','1') CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT '0',
  `o_cost_price` decimal(11, 3) NULL DEFAULT NULL COMMENT '欧元成本价',
  `wx_app_show` int(1) NULL DEFAULT 1 COMMENT '0 显示 1不显示',
  `show_sort` int(7) NULL DEFAULT 0,
  `funjian` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '组装图纸',
  `photo2` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '副图片',
  `photo3` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '副图片',
  `photo4` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '副图片',
  `price_bak` decimal(11, 3) NULL DEFAULT NULL COMMENT '更新前销售价',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `id`(`id`) USING BTREE,
  INDEX `name`(`name`) USING BTREE,
  INDEX `goods_no`(`goods_no`) USING BTREE,
  INDEX `goods_brand_id`(`brand_id`) USING BTREE,
  INDEX `goods_seach_index`(`material`, `fabric`, `painting`, `goods_name1`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 93195 CHARACTER SET = utf8 COLLATE = utf8_general_ci ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for goods_attribute
