-- ----------------------------
-- Table structure for inventory
-- ----------------------------
DROP TABLE IF EXISTS `inventory`;
CREATE TABLE `inventory`  (
  `id` int(11) UNSIGNED NOT NULL AUTO_INCREMENT,
  `purchase_item_id` int(11) NULL DEFAULT NULL,
  `put_in_storage_item_id` int(11) NULL DEFAULT NULL COMMENT '到货明细表Id',
  `order_delivery_item_id` int(11) NULL DEFAULT NULL COMMENT '销售送货Id',
  `order_return_item_id` int(11) NULL DEFAULT NULL COMMENT '销售退货Id',
  `transfer_item_id` int(11) NULL DEFAULT NULL COMMENT '调拨Id',
  `goods_id` int(11) NOT NULL COMMENT '商品id',
  `warehouse_id` int(11) NOT NULL COMMENT '库位id',
  `purchase_cost_price` decimal(35, 20) NULL DEFAULT 0.00000000000000000000 COMMENT '成本单价',
  `cost_price` decimal(35, 20) NULL DEFAULT 0.00000000000000000000 COMMENT '成本单价',
  `cost_price_bak` decimal(35, 20) NULL DEFAULT 0.00000000000000000000 COMMENT '成本单价',
  `count` decimal(35, 20) NULL DEFAULT 0.00000000000000000000 COMMENT '商品数量',
  `mwa` decimal(35, 20) NULL DEFAULT NULL COMMENT '加权平均单价',
  `type` tinyint(3) NULL DEFAULT 1 COMMENT '库存类型：1，在厂、2，在途、3，在库、4，出库',
  `status` tinyint(1) NULL DEFAULT 2 COMMENT '库存状态：1、死货，2、非死货',
  `remark` text CHARACTER SET utf8 COLLATE utf8_general_ci NULL COMMENT '备注',
  `create_user_id` int(11) NULL DEFAULT NULL COMMENT '操作人id',
  `create_date` int(11) NULL DEFAULT NULL COMMENT '操作时间',
  `update_user_id` int(11) NULL DEFAULT NULL COMMENT '操作人',
  `update_date` int(10) NULL DEFAULT NULL COMMENT '出库时间',
  `goods_element_id` int(11) NULL DEFAULT NULL,
  `is_settlement` int(2) NULL DEFAULT 1 COMMENT '是否参与结算0:不参与  1参与',
  `loss_reporting_item_id` int(11) NULL DEFAULT NULL,
  `excess_reporting_item_id` int(11) NULL DEFAULT NULL,
  `order_exchange_out_item_id` int(11) NULL DEFAULT NULL COMMENT '售后换货出库id',
  `order_exchange_in_item_id` int(11) NULL DEFAULT NULL COMMENT '售后换货入库id',
  `order_dismountin_in_item_id` int(11) NOT NULL,
  `order_dismountin_out_item_id` int(11) NOT NULL,
  `is_die` int(1) NOT NULL DEFAULT 0 COMMENT '是否是死货 0否  1是',
  `chuanhuo_count` int(11) NOT NULL DEFAULT 0,
  `inventory_falling_item_id` int(11) NOT NULL,
  `status1` int(2) NULL DEFAULT 1 COMMENT '1有主 绑定订单 2无主 3店样',
  `DT_remark` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL,
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `inv_search`(`goods_id`, `warehouse_id`, `put_in_storage_item_id`, `order_delivery_item_id`, `order_return_item_id`, `transfer_item_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 324344 CHARACTER SET = utf8 COLLATE = utf8_general_ci ROW_FORMAT = Dynamic;

-- ----------------------------
