-- ----------------------------
-- Table structure for jsj_goods
-- ----------------------------
DROP TABLE IF EXISTS `jsj_goods`;
CREATE TABLE `jsj_goods`  (
  `id` bigint(20) NOT NULL AUTO_INCREMENT,
  `goods_categories_id` bigint(20) NULL DEFAULT NULL COMMENT '商品分类ID',
  `goods_name` varchar(200) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '商品名',
  `goods_sn` varchar(200) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '商品ID',
  `goods_uint` char(50) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '商品计量单位',
  `goods_cost` decimal(11, 2) NOT NULL DEFAULT 1.00 COMMENT '商品成本价',
  `goods_price` decimal(11, 2) NOT NULL COMMENT '商品售价',
  `goods_arts` text CHARACTER SET utf8 COLLATE utf8_general_ci NULL COMMENT '商品规格',
  `create_time` int(10) NOT NULL COMMENT '创建时间',
  `create_user_id` bigint(20) NOT NULL COMMENT '创建者',
  `update_time` int(11) NOT NULL,
  `update_user_id` int(11) NOT NULL,
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `unique1`(`goods_name`, `goods_sn`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 2555 CHARACTER SET = utf8 COLLATE = utf8_general_ci ROW_FORMAT = Dynamic;

