-- Table structure for jsj_order_sales_double
-- ----------------------------
DROP TABLE IF EXISTS `jsj_order_sales_double`;
CREATE TABLE `jsj_order_sales_double`  (
  `id` int(11) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'id',
  `order_id` int(11) NOT NULL COMMENT '定单',
  `dept_id` int(11) NOT NULL COMMENT '部门',
  `emp_id` int(11) NOT NULL COMMENT '员工',
  `amount` decimal(11, 3) NOT NULL COMMENT '分配金额',
  `create_user_id` int(11) NULL DEFAULT NULL COMMENT '创建人',
  `create_time` int(10) NULL DEFAULT NULL COMMENT '创建时间',
  `update_user_id` int(11) NULL DEFAULT NULL COMMENT '更新人',
  `update_time` int(10) NULL DEFAULT NULL COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 847 CHARACTER SET = utf8 COLLATE = utf8_general_ci ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for jsj_orders
-- ----------------------------
DROP TABLE IF EXISTS `jsj_orders`;
CREATE TABLE `jsj_orders`  (
  `id` bigint(20) NOT NULL AUTO_INCREMENT,
  `order_sn` varchar(200) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '订单编号',
  `dept_id` int(11) NOT NULL,
  `dept_name` varchar(100) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL,
  `customer_id` bigint(20) NOT NULL COMMENT '客户id',
  `customer_name` varchar(200) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '客户姓名',
  `customer_mobile` varchar(20) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '客户联系电话',
  `customer_address` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '客户送货地址',
  `order_amount` decimal(11, 2) NOT NULL COMMENT '订单金额',
  `actual_amount` decimal(11, 2) NOT NULL COMMENT '实际成交额',
  `create_time` int(10) NOT NULL COMMENT '创建时间',
  `create_user_id` bigint(20) NOT NULL COMMENT '创建者',
  `delivery_time` int(11) NULL DEFAULT NULL COMMENT '送货时间',
  `create_user_mobile` varchar(20) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '设计师电话',
  `create_user_name` varchar(200) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '设计师姓名',
  `actual_payment` decimal(11, 2) NULL DEFAULT NULL COMMENT '实际收款',
  `pay_flg` tinyint(3) NOT NULL DEFAULT 0 COMMENT '账务确认状态',
  `purchase_flg` tinyint(3) NOT NULL COMMENT '采购申请',
  `jc_flg` tinyint(3) NOT NULL DEFAULT 0 COMMENT '采购申请，路总确认',
  `jc_memo` varchar(200) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '说明',
  `actual_purchase_flg` tinyint(3) NOT NULL DEFAULT 0 COMMENT '采购状态',
  `estimated_delivery_time` int(10) NULL DEFAULT NULL COMMENT '预计送货时间',
  `daohuo_flg` tinyint(3) NOT NULL DEFAULT 0 COMMENT '到货状态',
  `daohuo_time` int(10) NULL DEFAULT NULL COMMENT '到货时间',
  `making_flg` tinyint(3) NOT NULL DEFAULT 0 COMMENT '制作状态',
  `making_time` int(10) NULL DEFAULT NULL COMMENT '预计完成时间',
  `make_flg` tinyint(3) NOT NULL DEFAULT 0 COMMENT '制作完成',
  `make_time` int(10) NULL DEFAULT NULL COMMENT '完成时间',
  `anzhuang_flg` tinyint(3) NOT NULL DEFAULT 0 COMMENT '准备安装',
  `anzhuang_time` int(10) NULL DEFAULT NULL COMMENT '预计安装时间',
  `finish_flg` tinyint(3) NOT NULL DEFAULT 0 COMMENT '完结',
  `finish_time` int(10) NULL DEFAULT NULL COMMENT '完结时间',
  `design_fee_apply` tinyint(1) NULL DEFAULT 0,
  `return_memo` text CHARACTER SET utf8 COLLATE utf8_general_ci NULL COMMENT '退货说明',
  `memo` text CHARACTER SET utf8 COLLATE utf8_general_ci NULL COMMENT '备注说明',
  `is_tijiao` int(11) NULL DEFAULT 0 COMMENT '是否提交审核',
  `order_class` tinyint(3) NULL DEFAULT 1 COMMENT '1:定单 2:退单',
  `step` varchar(10) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT '总经理' COMMENT '审核用',
  `new_memo` text CHARACTER SET utf8 COLLATE utf8_general_ci NULL COMMENT '新订单备注',
  `return_order_id` int(11) NULL DEFAULT NULL COMMENT '退货单ID',
  `exchange_order_id` varchar(11) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '换货单ID',
  `order_sn_temp` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL,
  `is_cancel` int(2) NULL DEFAULT 0 COMMENT '是否作废 0否 1是',
  `delivery_status` int(1) NULL DEFAULT 1 COMMENT '送货状态：1、未处理，2、待送货，3，完结',
  `shouhou_fujian` int(1) NOT NULL DEFAULT 0,
  `status` int(1) NOT NULL DEFAULT 0,
  `gong_fee` decimal(10, 2) NOT NULL,
  `yiye_amount` decimal(11, 2) NOT NULL DEFAULT 0.00,
  `shejifei_amount` decimal(11, 2) NOT NULL DEFAULT 0.00,
  `yiye_fee_apply` int(2) NOT NULL DEFAULT 0,
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `order_sn`(`order_sn`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1568 CHARACTER SET = utf8 COLLATE = utf8_general_ci ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for jsj_orders_action
-- ----------------------------
DROP TABLE IF EXISTS `jsj_orders_action`;
CREATE TABLE `jsj_orders_action`  (
  `id` bigint(20) NOT NULL AUTO_INCREMENT,
