  PRIMARY KEY (`id`) USING BTREE
) ENGINE = MyISAM AUTO_INCREMENT = 3347 CHARACTER SET = utf8 COLLATE = utf8_general_ci ROW_FORMAT = Fixed;

-- ----------------------------
-- Table structure for jsj_orders_goods_temp
-- ----------------------------
DROP TABLE IF EXISTS `jsj_orders_goods_temp`;
CREATE TABLE `jsj_orders_goods_temp`  (
  `id` bigint(20) NOT NULL AUTO_INCREMENT,
  `customer_id` bigint(20) NULL DEFAULT NULL COMMENT '客户ID',
  `part` varchar(200) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '位置',
  `name` varchar(200) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '名称',
  `goods_id` bigint(20) NOT NULL COMMENT '商品ID',
  `goods_sn` varchar(200) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '商品型号',
  `goods_unit` char(50) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '计量单位',
  `goods_nubmer` decimal(11, 2) NOT NULL COMMENT '购买数量',
  `goods_price` decimal(11, 2) NOT NULL COMMENT '单价',
  `goods_amount` decimal(11, 2) NOT NULL COMMENT '金额',
  `goods_type` tinyint(3) NULL DEFAULT NULL COMMENT '商品类型',
  `type` tinyint(3) NULL DEFAULT NULL COMMENT '类型',
  `width` decimal(11, 2) NULL DEFAULT NULL COMMENT '窗宽',
  `height` decimal(11, 2) NULL DEFAULT NULL COMMENT '窗高',
  `pleat` decimal(11, 3) NULL DEFAULT NULL COMMENT '褶倍数',
  `width1` decimal(11, 2) NULL DEFAULT NULL COMMENT '幅宽',
