-- Table structure for missing_goods
-- ----------------------------
DROP TABLE IF EXISTS `missing_goods`;
CREATE TABLE `missing_goods`  (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `company_id` int(11) NOT NULL COMMENT '公司ID',
  `goods_name` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL,
  `dept_id` int(11) NULL DEFAULT NULL COMMENT '部门ID',
  `dept_name` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '部门名',
  `applicant_id` int(11) NULL DEFAULT NULL COMMENT '申请人ID',
  `applicant_name` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '申请人姓名',
  `apply_for_date` int(11) NULL DEFAULT NULL COMMENT '申请时间',
  `1st_confirm_id` int(11) NULL DEFAULT NULL COMMENT '1级确认人ID',
  `1st_confirm_name` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '1级确认人姓名',
  `1st_confirm_status` enum('3','2','1') CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '1:待确认,2:通过,4:重新确认',
  `1st_confirm_date` int(11) NULL DEFAULT NULL COMMENT '1级确认人时间',
  `1st_confirm_done` int(11) NULL DEFAULT NULL COMMENT '1级确认完成时间',
  `1st_confirm_time` int(11) NULL DEFAULT NULL,
  `2nd_confirm_id` int(11) NULL DEFAULT NULL COMMENT '2级确认人ID',
  `2nd_confirm_name` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '2级确认人姓名',
  `2nd_confirm_status` enum('3','2','1') CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '1:待确认,2:撤回,3:通过',
  `2nd_confirm_date` int(11) NULL DEFAULT NULL COMMENT '2级确认时间',
  `2nd_reply_date` int(11) NULL DEFAULT NULL COMMENT '撤回时间',
  `2nd_confirm_done` int(11) NULL DEFAULT NULL COMMENT '2级确认完成时间',
  `2nd_confirm_time` int(11) NULL DEFAULT NULL,
  `status` tinyint(3) NULL DEFAULT NULL COMMENT '状态。1:解决中,2：完成',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8 COLLATE = utf8_general_ci ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for monthly_balance
-- ----------------------------
DROP TABLE IF EXISTS `monthly_balance`;
CREATE TABLE `monthly_balance`  (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `status` tinyint(1) NULL DEFAULT NULL COMMENT '状态:0,1',
  `monthly_date` date NULL DEFAULT NULL COMMENT '月份',
  `inventory` decimal(35, 20) NULL DEFAULT NULL,
  `cash` decimal(35, 20) NULL DEFAULT NULL,
  `account_set` int(11) NULL DEFAULT NULL COMMENT '账套：50、大连，16、沈阳，89、石家庄,101、石家庄,107、唐愫',
  `create_user_id` int(11) NULL DEFAULT NULL COMMENT '创建人',
  `create_time` int(11) NULL DEFAULT NULL COMMENT '创建时间',
  `update_user_id` int(11) NULL DEFAULT NULL COMMENT '更新人',
  `update_time` int(11) NULL DEFAULT NULL COMMENT '更新时间',
  `is_back_monthly` int(2) NULL DEFAULT 0 COMMENT '是否可以反月结0：是  1：否',
  `is_del` int(2) NULL DEFAULT 0 COMMENT '是否删除0:否   1：是',
  `abstract` text CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL,
  `quzong_abstract` text CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL,
  `quzong_status` int(11) NOT NULL COMMENT '1 提交审核，曲总审核中  2同意  3驳回',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 866 CHARACTER SET = utf8 COLLATE = utf8_general_ci ROW_FORMAT = Dynamic;

