  `asset_init` decimal(35, 20) NULL DEFAULT NULL COMMENT '期初(资产类)总计',
  `asset_total` decimal(35, 20) NULL DEFAULT NULL COMMENT '期末(资产类)总计',
  `lelist` text CHARACTER SET utf8 COLLATE utf8_general_ci NULL COMMENT '负责及权益类',
  `lelist_init` decimal(35, 20) NULL DEFAULT NULL COMMENT '期初(负责及权益类)总计',
  `lelist_total` decimal(35, 20) NULL DEFAULT NULL COMMENT '期末(负责及权益类)总计',
  `is_del` int(2) NULL DEFAULT 0 COMMENT '是否显示0是   1否',
  `create_date` datetime NULL DEFAULT NULL,
  `create_user_id` int(11) NULL DEFAULT NULL,
  `update_time` datetime NULL DEFAULT NULL,
  `update_user_id` int(11) NULL DEFAULT NULL,
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = MyISAM AUTO_INCREMENT = 2183 CHARACTER SET = utf8 COLLATE = utf8_general_ci ROW_FORMAT = Dynamic;

