-- Table structure for mp_orders
-- ----------------------------
DROP TABLE IF EXISTS `mp_orders`;
CREATE TABLE `mp_orders`  (
  `id` bigint(20) NOT NULL AUTO_INCREMENT,
  `order_sn` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '订单编号',
  `user_id` bigint(20) NOT NULL COMMENT '设计师ID',
  `product_id` bigint(20) NOT NULL COMMENT '产品id',
  `quantity` int(10) NOT NULL DEFAULT 1 COMMENT '数量',
  `score` decimal(11, 2) NOT NULL COMMENT '兑换积分',
  `create_time` int(10) NOT NULL COMMENT '提交时间',
  `delivery_time` int(10) NULL DEFAULT NULL COMMENT '送货时间',
  `status` tinyint(3) NOT NULL DEFAULT 1 COMMENT '订单状态 1：待处理，2：已发货，3：到店自提',
  `update_user_id` bigint(20) NULL DEFAULT NULL,
  `update_time` int(10) NULL DEFAULT NULL,
  `memo` text CHARACTER SET utf8 COLLATE utf8_general_ci NULL,
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 7 CHARACTER SET = utf8 COLLATE = utf8_general_ci ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for mp_permissions
-- ----------------------------
DROP TABLE IF EXISTS `mp_permissions`;
CREATE TABLE `mp_permissions`  (
  `id` bigint(20) NOT NULL AUTO_INCREMENT,
  `pid` bigint(20) NOT NULL COMMENT '上级权限',
  `permission_id` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL,
