-- ----------------------------
-- Table structure for order_delivery
-- ----------------------------
DROP TABLE IF EXISTS `order_delivery`;
CREATE TABLE `order_delivery`  (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `order_sn` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '定单号',
  `order_no` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '单号',
  `order_type` tinyint(1) NULL DEFAULT 1 COMMENT '定单类型',
  `dept_id` int(11) NULL DEFAULT NULL COMMENT '部门ID',
  `customer_user_id` int(11) NULL DEFAULT NULL COMMENT '客户统一ID',
  `customer_id` int(11) NULL DEFAULT NULL COMMENT '客户ID',
  `customer_name` varchar(100) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '客户姓名',
  `customer_mobile` varchar(100) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '联系电话',
  `customer_address` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '送货地址',
  `temp_delivery_date` date NULL DEFAULT NULL COMMENT '预计送货时间',
  `delivery_date` date NULL DEFAULT NULL COMMENT '送货时间',
  `driver` varchar(100) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '司机',
  `emp` varchar(100) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '工人',
  `cost` decimal(35, 20) NULL DEFAULT NULL COMMENT '送货成本',
  `cost_bak` decimal(35, 20) NULL DEFAULT NULL COMMENT '送货成本',
  `price` decimal(35, 20) NULL DEFAULT NULL COMMENT '送货金额',
  `status` tinyint(1) NULL DEFAULT 1 COMMENT '状态：1、准备出库，2、送货中，3、部分完结，4、完结',
  `remark` text CHARACTER SET utf8 COLLATE utf8_general_ci NULL COMMENT '备注',
  `create_user_id` int(11) NULL DEFAULT NULL COMMENT '创建者',
  `create_time` int(10) NULL DEFAULT NULL COMMENT '创建时间',
  `update_user_id` int(11) NULL DEFAULT NULL COMMENT '更新者',
  `update_time` int(10) NULL DEFAULT NULL COMMENT '更新时间',
  `account_date` date NULL DEFAULT NULL COMMENT '过账时间 ',
  `is_hongchong` int(2) NULL DEFAULT 0 COMMENT '是否开启红冲功能0：否    1：是',
  `is_monthly` int(2) NULL DEFAULT 0 COMMENT '月结标志0：未月结  1：以月结',
  `is_del` int(2) NULL DEFAULT 0 COMMENT '是否删除标志0：否 1：是',
  `is_caigouqueren` int(2) NULL DEFAULT 0 COMMENT '采购是否确认0 否   1是',
  `caigou_remark` text CHARACTER SET utf8 COLLATE utf8_general_ci NULL COMMENT '采购备注',
  `quzong_abstract` text CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL,
  `quzong_status` int(11) NOT NULL COMMENT '1 提交审核，曲总审核中  2同意  3驳回',
  `hongchong_abstract` text CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL,
  `shejifei` decimal(10, 2) NULL DEFAULT NULL COMMENT '设计费',
  `remark1` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL,
  `signature` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '客户签字',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `dept_id`(`dept_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 56470 CHARACTER SET = utf8 COLLATE = utf8_general_ci ROW_FORMAT = Dynamic;

