  `driver` varchar(100) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '司机',
  `emp` varchar(100) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '工人',
  `status` tinyint(1) NULL DEFAULT 1 COMMENT '状态：1、准备出库，2、送货中，3、部分完结，4、完结',
  `remark` text CHARACTER SET utf8 COLLATE utf8_general_ci NULL COMMENT '备注',
  `create_user_id` int(11) NULL DEFAULT NULL COMMENT '创建者',
  `create_time` int(10) NULL DEFAULT NULL COMMENT '创建时间',
  `update_user_id` int(11) NULL DEFAULT NULL COMMENT '更新者',
  `update_time` int(10) NULL DEFAULT NULL COMMENT '更新时间',
  `price_differences` decimal(20, 5) NULL DEFAULT NULL COMMENT '销售差价',
  `cost_price_differences` decimal(20, 5) NULL DEFAULT NULL COMMENT '成本价差价',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 456 CHARACTER SET = utf8 COLLATE = utf8_general_ci ROW_FORMAT = Dynamic;

