-- ----------------------------
-- Table structure for order_purchase
-- ----------------------------
DROP TABLE IF EXISTS `order_purchase`;
CREATE TABLE `order_purchase`  (
  `id` int(11) UNSIGNED NOT NULL AUTO_INCREMENT,
  `purchase_order_no` varchar(20) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '采购订单号',
  `chic_no` int(11) NULL DEFAULT NULL,
  `type` tinyint(1) NULL DEFAULT 1 COMMENT '采购单类型：1、销售单，2、需求单',
  `dept_id` int(11) NULL DEFAULT NULL COMMENT '销售店面id',
  `dept_name` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '店名',
  `dept_phone` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '电话',
  `factory_id` varchar(100) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '涉及待采购商品的厂家id',
  `warehouse_id` int(11) NULL DEFAULT NULL COMMENT '收货仓库',
  `order_id` varchar(100) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT '' COMMENT '销售单号',
  `customer_id` int(11) NULL DEFAULT NULL COMMENT '顾客id',
  `customer_name` varchar(100) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '顾客姓名',
  `customer_contact` varchar(30) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '联系电话',
  `customer_address` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '送货地址',
  `amount` decimal(11, 3) NULL DEFAULT NULL COMMENT '总计',
  `dis` decimal(3, 2) NULL DEFAULT NULL COMMENT '折扣',
  `order_date` int(11) NULL DEFAULT NULL COMMENT '订货日期',
  `delivery_date` int(11) NULL DEFAULT NULL COMMENT '送货日期',
  `status` tinyint(3) NULL DEFAULT 1 COMMENT '状态：1、订单',
  `pay_status` tinyint(1) NULL DEFAULT 0 COMMENT '支付状态：0、未发起申请，1、已发起申请，2、采购主管审核中，4、会计处理中，5、账务主管审核中，6、总经理审核中，7，出纳汇款中，8、已支付，9、退款已确认',
  `remark` text CHARACTER SET utf8 COLLATE utf8_general_ci NULL,
  `create_date` int(11) NULL DEFAULT NULL COMMENT '创建时间',
  `create_user_id` int(11) NULL DEFAULT NULL COMMENT '创建人id',
  `create_user_name` varchar(100) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '创建人姓名',
  `update_date` int(11) NULL DEFAULT NULL COMMENT '更新时间',
  `update_user_id` int(11) NULL DEFAULT NULL COMMENT '更新人id',
  `update_user_name` varchar(100) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '更新人姓名',
  `zuofeireason` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL,
  `lianxihou_delivery_date` int(11) NULL DEFAULT NULL,
  `flag` int(11) NULL DEFAULT 0,
  `adjusting_id` int(11) NULL DEFAULT NULL,
  `change_status` int(11) NULL DEFAULT 0,
  `tuihuo_id` int(11) NULL DEFAULT NULL,
  `allnormal` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL,
  `allactuall` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL,
  `allcut` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL,
  `cuttime` datetime NULL DEFAULT NULL,
  `check_status` tinyint(1) NULL DEFAULT 1,
  `check_time` int(10) NULL DEFAULT NULL,
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 22474 CHARACTER SET = utf8 COLLATE = utf8_general_ci ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for order_purchase_change
-- ----------------------------
DROP TABLE IF EXISTS `order_purchase_change`;
CREATE TABLE `order_purchase_change`  (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `order_purchase_id` int(11) NULL DEFAULT NULL COMMENT 'order_purchase表的id',
  `goods_id` int(11) NULL DEFAULT NULL COMMENT '商品id',
  `goods_name` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '商品名称',
  `order_purchase_item_id` int(11) NULL DEFAULT NULL COMMENT 'order_purchase_item表的id',
  `goods_no` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '商品品号',
  `sales_number` int(11) NULL DEFAULT NULL COMMENT '销售的数量',
  `purchase_number` int(11) NULL DEFAULT NULL COMMENT '采购的数量',
  `reason` varchar(11) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '采购数量与销售数量不同的原因',
  `create_time` int(11) NULL DEFAULT NULL COMMENT '创建时间',
  `create_id` int(11) NULL DEFAULT NULL COMMENT '创建人id',
  `status` int(11) NULL DEFAULT 0 COMMENT '状态：采购数量改变：0 默认，1 提交，2 刘芳华同意，3董总同意，4刘芳华驳回，5董总驳回 ',
  `reasonliu` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '刘芳华审核意见',
  `reasondong` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '董总审核意见',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 714 CHARACTER SET = utf8 COLLATE = utf8_general_ci ROW_FORMAT = Dynamic;

