-- ----------------------------
-- Table structure for order_purchase_item
-- ----------------------------
DROP TABLE IF EXISTS `order_purchase_item`;
CREATE TABLE `order_purchase_item`  (
  `id` int(11) UNSIGNED NOT NULL AUTO_INCREMENT,
  `purchase_id` int(11) NULL DEFAULT NULL COMMENT '采购单id',
  `order_id` int(11) NULL DEFAULT NULL COMMENT '销售单id',
  `order_user_detail_id` int(11) NULL DEFAULT NULL COMMENT '定单商品ID',
