  `factory_delivery_date` int(11) NULL DEFAULT NULL COMMENT '厂家交货日期',
  `warehouse_id` int(11) NULL DEFAULT NULL,
  `brand_id` int(11) NULL DEFAULT NULL COMMENT '品牌id',
  `goods_id` int(11) NULL DEFAULT NULL COMMENT '商品id',
  `goods_no` varchar(100) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '商品品号',
  `goods_name` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '商品名称',
  `goods_size` varchar(100) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '商品尺寸',
  `goods_unit` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '商品单位',
  `sales_volume` decimal(11, 3) NULL DEFAULT NULL COMMENT '销售数量',
  `shiji_volume` decimal(11, 3) NULL DEFAULT NULL,
  `goods_cost_price` decimal(11, 3) NULL DEFAULT NULL COMMENT '系统成本',
  `dis` decimal(3, 2) NULL DEFAULT NULL COMMENT '折扣',
  `dis_price` decimal(11, 3) NULL DEFAULT NULL COMMENT '折后价格',
  `amount` decimal(11, 3) NULL DEFAULT NULL COMMENT '合计',
  `purchase_price` decimal(11, 3) NULL DEFAULT NULL COMMENT '采购单价',
  `purchase_status` tinyint(1) NULL DEFAULT 1 COMMENT '采购状态：1、采购，2不采购',
  `inventory_status` tinyint(1) NULL DEFAULT 1 COMMENT '库存状态：1、在厂，2、待入库，3、在库，4、出库',
  `status` tinyint(3) NULL DEFAULT 1 COMMENT '状态',
  `memo` text CHARACTER SET utf8 COLLATE utf8_general_ci NULL COMMENT '备注',
  `shouhou_memo` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL,
  `outwarehouse_id` int(11) NULL DEFAULT NULL,
  `upto_warehouse_time` int(11) NULL DEFAULT NULL,
  `songhuoshijian` int(11) NULL DEFAULT NULL,
  `fenjiemingxi` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL,
  `order_user_salesvolume` int(11) NULL DEFAULT NULL,
  `report_flg` tinyint(3) NULL DEFAULT 0 COMMENT '上报状态',
  `delivery_time` int(10) NULL DEFAULT NULL COMMENT '发货操作时间',
  `upto_warehouse_id` bigint(20) NULL DEFAULT NULL COMMENT '上报入库明细表ID',
  `remark` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '厂家备注',
  `create_user_id` int(11) NULL DEFAULT NULL COMMENT '创建者',
  `create_time` int(10) NULL DEFAULT NULL COMMENT '创建时间',
  `update_user_id` int(11) NULL DEFAULT NULL COMMENT '更新者',
  `update_time` int(10) NULL DEFAULT NULL COMMENT '更新时间',
  `no_caigou_warehouse_id` int(11) NULL DEFAULT NULL COMMENT '不采购出库库位',
  `is_del` int(1) NOT NULL DEFAULT 0 COMMENT '是否删除',
  `goods_status` int(11) NOT NULL DEFAULT 0 COMMENT '商品当前状态2 在厂 3在途 4在库 5配送中 6出库',
  `is_die` int(1) NOT NULL DEFAULT 0 COMMENT '是否是死货 0否  1是',
  `ar_no` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL,
  `yujimonth` int(11) NOT NULL,
  `yujidate` date NOT NULL,
  `chuanhuo_count` int(11) NOT NULL DEFAULT 0,
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 88599 CHARACTER SET = utf8 COLLATE = utf8_general_ci ROW_FORMAT = Dynamic;

