-- ----------------------------
-- Table structure for order_purchase_pay
-- ----------------------------
DROP TABLE IF EXISTS `order_purchase_pay`;
CREATE TABLE `order_purchase_pay`  (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `purchase_id` int(11) NOT NULL COMMENT '采购单ID',
  `purchase_no` varchar(100) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '采购单号',
  `factory_id` int(11) NOT NULL COMMENT '供应商ID',
  `factory_name` varchar(100) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '供应商全名',
  `payee` varchar(100) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '收款人',
  `purchase_amount` decimal(35, 20) NOT NULL COMMENT '采购金额',
  `actual_pay` decimal(35, 20) NULL DEFAULT NULL COMMENT '实际支付金额',
  `remitting_bank` varchar(100) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '汇款银行',
  `remitting_bank_code` varchar(100) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '汇款账号',
  `remitting_time` int(10) NOT NULL COMMENT '汇款日期',
  `remitting_purpose` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL,
  `remark` text CHARACTER SET utf8 COLLATE utf8_general_ci NULL,
  `status` tinyint(1) NOT NULL DEFAULT 1 COMMENT '状态：1、发起申请，2、采购主管审核，3、会计审核，4、账务主管审核，5、总经理审核，6、汇款中，7、完结，8、驳回',
  `deduction_id` int(11) NULL DEFAULT NULL COMMENT '抵扣项目',
  `deduction_amount` decimal(35, 20) NULL DEFAULT NULL COMMENT '抵扣金额',
  `pay_subject_id` int(11) NULL DEFAULT NULL COMMENT '支出账户',
