-- ----------------------------
-- Table structure for order_user
-- ----------------------------
DROP TABLE IF EXISTS `order_user`;
CREATE TABLE `order_user`  (
  `id` bigint(20) NOT NULL AUTO_INCREMENT,
  `order_sn_temp` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL,
  `order_sn` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '订单号',
  `company_id` int(11) NULL DEFAULT NULL COMMENT '公司id',
  `company_name` varchar(100) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '公司名',
  `dept_id` int(11) NULL DEFAULT NULL COMMENT '部门id',
  `dept_name` varchar(100) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '部门全名',
  `dept_tel` varchar(100) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '部门电话',
  `user_id` int(11) NULL DEFAULT NULL COMMENT '用户id',
  `emp_id` int(11) NULL DEFAULT NULL COMMENT '员工ID',
  `user_name` varchar(200) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '制单人全名',
  `customer_user_id` int(11) NULL DEFAULT NULL COMMENT '客户UserID',
  `client_id` bigint(20) NULL DEFAULT NULL COMMENT '客户id',
  `client_name` varchar(100) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '客户姓名',
  `client_address` varchar(200) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '送货地址',
  `client_mobile` varchar(100) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '客户电话',
  `client_mobile_bak` varchar(100) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '备用电话',
  `type` tinyint(1) NULL DEFAULT 1 COMMENT '定单类型：1、销售单，2、店面需求单',
  `status` tinyint(5) NULL DEFAULT 0 COMMENT '订单状态 0:预约 1：审核 2：未上报 3：作废 9：有效 10：采购 11：发货 12：入库 13：送货 14：完结',
  `order_class` tinyint(3) NULL DEFAULT 1 COMMENT '1:定单 2:退单',
  `reg_date` int(11) NULL DEFAULT NULL COMMENT '订单添加时间',
  `report_date` int(11) NULL DEFAULT 0,
  `order_give` int(11) NULL DEFAULT NULL COMMENT '预计送货日期',
  `actual_delivery_time` int(10) NULL DEFAULT NULL COMMENT '实际送货时间',
  `finish` int(11) NULL DEFAULT NULL COMMENT '完结时间',
  `goods_totalprice` int(11) NULL DEFAULT NULL COMMENT '商品总价格',
  `actualmoney` decimal(13, 2) NULL DEFAULT NULL COMMENT '实际成交价',
  `totalmoney` decimal(13, 2) NULL DEFAULT NULL COMMENT '总价',
  `total_pix` float(3, 2) NOT NULL DEFAULT 1.00 COMMENT '折扣',
  `customer_account` decimal(11, 2) NOT NULL DEFAULT 0.00 COMMENT '当前支付金额',
  `all_pay_flag` tinyint(1) NULL DEFAULT 0 COMMENT '全款支付标记',
  `final_payment` tinyint(3) NULL DEFAULT 0 COMMENT '支付状态',
  `step` varchar(10) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT '总经理' COMMENT '审核用',
  `qzphoto` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '签字照片',
  `description` text CHARACTER SET utf8 COLLATE utf8_general_ci NULL COMMENT '后台备注',
  `dome` mediumtext CHARACTER SET utf8 COLLATE utf8_general_ci NULL COMMENT '客户备注',
  `check_centent` text CHARACTER SET utf8 COLLATE utf8_general_ci NULL COMMENT '审核信息',
  `remark` text CHARACTER SET utf8 COLLATE utf8_general_ci NULL COMMENT '店面后勤需求',
  `fc_flg` tinyint(1) NULL DEFAULT 0 COMMENT '财务确认可送货',
  `fconfirm` tinyint(3) NULL DEFAULT 0 COMMENT '财务确认状态',
  `fc_username` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '财务确认人',
  `fc_time` int(10) NULL DEFAULT NULL COMMENT '财务确认时间',
  `pconfirm` tinyint(3) NULL DEFAULT 0 COMMENT '采购确认状态',
  `pc_username` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '采购确认人',
  `allocation` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '分配----作废',
  `appmoney` int(11) NULL DEFAULT 0 COMMENT '追加费用',
  `display` tinyint(3) NULL DEFAULT 0,
  `performance` tinyint(3) NULL DEFAULT NULL COMMENT '作废',
  `performance_time` int(11) NULL DEFAULT NULL COMMENT '作废',
  `check_flg` tinyint(3) NULL DEFAULT 0,
  `intention_sn` varchar(100) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL,
  `intention` int(11) NULL DEFAULT NULL,
  `status2` tinyint(3) NULL DEFAULT 0 COMMENT '送货明细状态',
  `history_status` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL,
  `total_cost` decimal(35, 20) NULL DEFAULT NULL,
  `beizhu` text CHARACTER SET utf8 COLLATE utf8_general_ci NULL,
  `balance` varchar(20) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT '0' COMMENT '已用余额总计',
  `purchase_order_id` int(11) NULL DEFAULT NULL COMMENT '采购单id',
  `order_over_memo` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL,
  `tuihuo_reason` int(4) NULL DEFAULT NULL,
  `orderchulistatus` int(11) NULL DEFAULT 1,
  `lianxihou_order_give` int(11) NULL DEFAULT NULL,
  `issonghuo` int(11) NULL DEFAULT 1,
  `recommend_name` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL,
  `recommend_flag` int(11) NULL DEFAULT 0,
  `design_fee_apply` tinyint(3) NULL DEFAULT 0 COMMENT '设计费支付标记',
  `brand_id` int(11) NULL DEFAULT NULL COMMENT '家具品牌',
  `is_tijiao` int(4) NULL DEFAULT 0,
  `cade` int(11) NULL DEFAULT 0 COMMENT '银行卡 作废',
  `cash` int(11) NULL DEFAULT 0 COMMENT '现金 作废',
  `transfer` int(11) NULL DEFAULT 0 COMMENT '转帐 作废',
  `cheque` int(11) NULL DEFAULT 0 COMMENT '支票 作废',
  `market` int(11) NULL DEFAULT 0 COMMENT '商城代收 作废',
  `transfer_no` varchar(200) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '转帐帐号 作废',
  `province_code` varchar(6) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '省 编号',
  `city_code` varchar(6) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '市 编号',
  `area_code` varchar(6) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '区 编号',
  `pconfirm1` tinyint(3) NULL DEFAULT 0 COMMENT '采购退货确认状态',
  `pconfirm1_user` int(11) NULL DEFAULT NULL,
  `pconfirm1_time` int(10) NULL DEFAULT NULL,
  `return_order_id` int(11) NULL DEFAULT NULL COMMENT '退货单ID',
  `exchange_order_id` int(11) NULL DEFAULT NULL COMMENT '换货单ID',
  `return_memo` text CHARACTER SET utf8 COLLATE utf8_general_ci NULL COMMENT '退单说明',
  `new_memo` text CHARACTER SET utf8 COLLATE utf8_general_ci NULL,
  `apply_count` int(3) NULL DEFAULT 0 COMMENT '设计费申请次数',
  `is_change` tinyint(1) NULL DEFAULT 0 COMMENT '是否退换货  0：否  1：是',
  `warehouse_id` int(5) NULL DEFAULT NULL COMMENT '自提商品出库库位',
  `is_ajmy` int(1) NULL DEFAULT 0,
  `ajmy_order_id` int(11) NOT NULL,
  `from_emp_id` int(11) NOT NULL,
  `from_emp_time` int(11) NOT NULL,
  `ajmy_pay` tinyint(1) UNSIGNED NOT NULL DEFAULT 0 COMMENT 'ajmy付款',
  `shejifei_amount` decimal(11, 2) NOT NULL COMMENT '设计费金额',
  `wage_flg` tinyint(1) UNSIGNED NOT NULL DEFAULT 0 COMMENT '工资处理状态',
  `tidian` float(4, 3) NULL DEFAULT NULL COMMENT '提点',
  `progressive_increase` tinyint(1) UNSIGNED NULL DEFAULT 0 COMMENT '递增标识位',
  `dianzhang_jiati` tinyint(1) NULL DEFAULT NULL COMMENT '管理层加提标识位',
  `digital_signature` text CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL,
  `create_digital_signature_time` int(11) NOT NULL,
  `update_digital_signature_time` int(11) NOT NULL,
  `old_status` int(11) NOT NULL,
  `yiye_fee_apply` int(11) NOT NULL DEFAULT 0,
  `yiye_amount` decimal(11, 2) NOT NULL,
  `shouhou_fujian` int(1) NOT NULL DEFAULT 0,
  `is_report_mpos` int(2) NOT NULL DEFAULT 0 COMMENT '是否上报mpos 0否  1是',
  `is_xianhou_flg` int(1) NOT NULL DEFAULT 0,
  `is_qingyang_flg` tinyint(1) UNSIGNED NOT NULL DEFAULT 0 COMMENT '清样',
  `caigou_return_memo` text CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL,
  `emp_wage_flg` tinyint(1) NULL DEFAULT 0,
  `is_baili` int(2) NOT NULL DEFAULT 0,
  `baili_tijiao_approve` int(2) NOT NULL DEFAULT 0,
  `baili_guiti_approve` int(2) NOT NULL DEFAULT 0,
  `caigou_lock` int(2) NOT NULL DEFAULT 0,
  `damages` decimal(10, 2) NOT NULL,
  `damages_date` date NOT NULL,
  `lingshou_id` int(11) NULL DEFAULT NULL,
  `is_xiaochengxu` int(2) NULL DEFAULT 0,
  `cus_qianshou` int(2) NULL DEFAULT 0,
  `temp_order_id` int(11) NULL DEFAULT 0,
  `dis_point_account` decimal(10, 2) NULL DEFAULT NULL COMMENT '提点金额',
  `xiaohongshu` decimal(10, 2) NULL DEFAULT NULL COMMENT '小红书扣点',
  `platform_id` int(11) NULL DEFAULT NULL COMMENT '销售平台',
  `action_flg` tinyint(1) UNSIGNED NULL DEFAULT 0 COMMENT '订单处理状态',
  `platform_flg` tinyint(1) NULL DEFAULT 0 COMMENT '销售平台财务确认',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `id`(`id`, `order_sn`, `client_name`, `client_address`, `client_mobile`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 66823 CHARACTER SET = utf8 COLLATE = utf8_general_ci ROW_FORMAT = Dynamic;

