  `goods_name` varchar(250) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL,
  `photo` varchar(200) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL,
  `size` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '规格',
  `goods_unit` varchar(10) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL,
  `curtom_number` decimal(13, 3) NULL DEFAULT NULL,
  `goods_cost_price` decimal(11, 2) NULL DEFAULT NULL,
  `goods_price` decimal(11, 2) NULL DEFAULT NULL COMMENT '产品价格',
  `actual_price` decimal(13, 2) NULL DEFAULT NULL COMMENT '实际单价',
  `curtom_money` decimal(13, 2) NULL DEFAULT NULL,
  `pick` tinyint(3) NULL DEFAULT 0 COMMENT '0 送货  1 自提',
  `property` varchar(20) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '正常',
  `class` varchar(100) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT '家具' COMMENT '类型',
  `dis` decimal(21, 20) NULL DEFAULT 1.00000000000000000000 COMMENT '单品折扣',
  `reg_date` int(11) NULL DEFAULT NULL,
  `goods_offprice` int(11) NULL DEFAULT NULL COMMENT '特惠价(作废)',
  `goods_rprice` int(11) NULL DEFAULT NULL COMMENT '作废',
  `status` tinyint(3) NULL DEFAULT NULL,
  `condition` varchar(100) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '退货采购说明',
  `reason` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '退货店面理由',
  `purchase_status` tinyint(1) NULL DEFAULT 1 COMMENT '采购状态：1、未处理，2、在厂，3、在途 4、在库',
  `status1` tinyint(3) NULL DEFAULT 0 COMMENT '送货明细表选状态  送：0  暂时不送：1 已送货',
  `delivery_status` tinyint(1) NULL DEFAULT 1 COMMENT '送货状态：1、未处理，2、待送货，3，完结',
  `inventory_status` tinyint(1) NULL DEFAULT 1 COMMENT '库存状态：1、待入库，2、已入库，3、已出库',
  `return_status` tinyint(1) NULL DEFAULT 0 COMMENT '退货状态',
  `chanpinquxiang` int(4) NULL DEFAULT NULL,
  `goodschulistatus` int(11) NULL DEFAULT 0,
  `goodschulimemo` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL,
  `sku_description` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT 'chic厂家描述',
  `new_flg` tinyint(1) NULL DEFAULT NULL COMMENT '新商品ID',
  `return_status1` tinyint(1) NULL DEFAULT 0 COMMENT '退换货中的要退货生成的标志',
  `new_flg1` tinyint(1) NULL DEFAULT 0 COMMENT '退换货中新增换货的标志位',
  `ajmy_z_detail_id` int(11) NULL DEFAULT 0,
  `update_user_id` int(11) NOT NULL,
  `update_time` int(11) NOT NULL,
  `is_caigou_return` int(1) NOT NULL DEFAULT 0 COMMENT '采购是否可以退货',
  `create_user_id` int(11) NOT NULL,
  `create_time` int(11) NOT NULL,
  `return_user` int(11) NOT NULL DEFAULT 0,
  `goods_place` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL,
  `goods_technology` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL,
  `detail_remark` text CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL,
  `is_transshipment` int(11) NOT NULL DEFAULT 0 COMMENT '是否串货0 否   1是',
  `ar_no` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL,
  `warehouse_id` int(11) NOT NULL COMMENT '锁定库位',
  `inv_goods_id` int(11) NULL DEFAULT NULL COMMENT '库存商品ID',
  `lingshou_item_id` int(11) NULL DEFAULT NULL,
  `sales_type` int(11) NULL DEFAULT NULL COMMENT '1在途  2在库  3预定',
  `dis_point` float(4, 3) NULL DEFAULT NULL COMMENT '折扣提点',
  `dis_point_account` decimal(10, 2) NULL DEFAULT NULL COMMENT '提点金额',
  `qingyang` tinyint(1) UNSIGNED NULL DEFAULT 0 COMMENT '清样',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `order_user_detail_search_index`(`id`, `pid`, `purchase_id`, `delivery_id`, `brand_id`, `goods_id`, `goods_no`, `goods_name`, `lingshou_item_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 253008 CHARACTER SET = utf8 COLLATE = utf8_general_ci ROW_FORMAT = Dynamic;

