-- ----------------------------
-- Table structure for orders
-- ----------------------------
DROP TABLE IF EXISTS `orders`;
CREATE TABLE `orders`  (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `order_number` varchar(100) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '单号',
  `temp_order_number` varchar(100) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '关联单号',
  `status` tinyint(3) NULL DEFAULT NULL COMMENT '状态',
  `type` tinyint(3) NULL DEFAULT NULL COMMENT '类型',
  `dept_id` int(11) NULL DEFAULT NULL COMMENT '部门ID',
  `dept_name` varchar(100) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '部门名称',
  `dept_contact_number` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '部门联系方式',
  `emp_id` int(11) NULL DEFAULT NULL COMMENT '制单人ID',
  `emp_name` varchar(100) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '制单人',
  `customer_id` int(11) NULL DEFAULT NULL COMMENT '客户ID',
  `customer_name` varchar(100) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '客户姓名',
  `delivery_address` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '送货地址',
  `contact_number` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '联系方式',
  `standby _contact_number` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '第二联系方式',
  `create_time` int(11) NULL DEFAULT NULL COMMENT '创建时间',
  `temp_delivery_time` int(11) NULL DEFAULT NULL COMMENT '预计送货时间',
  `actual_delivery_time` int(11) NULL DEFAULT NULL COMMENT '实际送货时间',
  `sales_price` int(11) NULL DEFAULT NULL COMMENT '零售价',
  `transaction_price` decimal(35, 20) NULL DEFAULT NULL COMMENT '成交价',
  `cost_price` int(11) NULL DEFAULT NULL COMMENT '成本',
  `order_discount` float(3, 2) NULL DEFAULT NULL COMMENT '折扣',
  `memo` mediumtext CHARACTER SET utf8 COLLATE utf8_general_ci NULL COMMENT '备注',
  `description` text CHARACTER SET utf8 COLLATE utf8_general_ci NULL COMMENT '描述',
  `step` varchar(10) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '阶段',
  `is_confirm` int(1) NULL DEFAULT 0 COMMENT '是否确认0：否   1：是',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `dept_id`(`dept_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 190 CHARACTER SET = utf8 COLLATE = utf8_general_ci ROW_FORMAT = Dynamic;

