-- ----------------------------
-- Table structure for payment_order
-- ----------------------------
DROP TABLE IF EXISTS `payment_order`;
CREATE TABLE `payment_order`  (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `bill_sn` varchar(100) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL,
  `current_type` int(11) NOT NULL COMMENT '往来单位类型',
  `current_id` int(11) NOT NULL COMMENT '往来单位ID',
  `current_name` varchar(100) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '往来单位全名',
  `account_set` int(3) NULL DEFAULT NULL COMMENT '账套：1、大连，2、沈阳，3、石家庄',
  `dept_id` int(11) NOT NULL,
  `cash_flow_subject_id` int(11) NOT NULL COMMENT '现金流科目',
  `pay_bank_id` int(11) NOT NULL COMMENT '支付银行',
  `amount` decimal(11, 2) NOT NULL COMMENT '实付金额',
  `create_date` date NOT NULL,
  `abstract` text CHARACTER SET utf8 COLLATE utf8_general_ci NULL COMMENT '摘要',
  `status` tinyint(1) NOT NULL DEFAULT 1 COMMENT '状态：1、草稿，2、单据',
  `remark` text CHARACTER SET utf8 COLLATE utf8_general_ci NULL COMMENT '附加说明',
  `create_user_id` int(11) NOT NULL,
  `create_time` int(10) NULL DEFAULT NULL,
  `approver` int(11) NULL DEFAULT NULL COMMENT '审批人',
  `approve_time` int(10) NULL DEFAULT NULL COMMENT '审批时间',
  `fee_type` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL,
  `fee_id` int(11) NOT NULL,
  `dingdanhao` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL,
  `update_time` int(11) NOT NULL,
  `update_user_id` int(11) NOT NULL,
  `quzong_abstract` text CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL,
  `quzong_status` int(11) NOT NULL COMMENT '1 提交审核，曲总审核中  2同意  3驳回',
  `hongchong_abstract` text CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL,
  `is_lejuan` int(1) NOT NULL DEFAULT 0,
  `zhizhi_flg` int(1) NULL DEFAULT 0,
  `is_del` int(1) NOT NULL DEFAULT 0,
  `biaozhu` int(11) NOT NULL,
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `current_id`(`current_id`) USING BTREE,
  INDEX `dept_id`(`dept_id`) USING BTREE,
  INDEX `payment_order_search_index`(`id`, `bill_sn`, `cash_flow_subject_id`, `pay_bank_id`, `fee_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 46307 CHARACTER SET = utf8 COLLATE = utf8_general_ci ROW_FORMAT = Dynamic;

