  `goods_id` int(11) NOT NULL COMMENT '商品id',
  `warehouse_id` int(11) NOT NULL COMMENT '库位id',
  `purchase_cost_price` decimal(35, 20) NULL DEFAULT 0.00000000000000000000 COMMENT '成本单价',
  `cost_price` decimal(35, 20) NULL DEFAULT 0.00000000000000000000 COMMENT '成本单价',
  `count` decimal(35, 20) NULL DEFAULT 0.00000000000000000000 COMMENT '商品数量',
  `mwa` decimal(35, 20) NULL DEFAULT NULL COMMENT '加权平均单价',
  `status` tinyint(1) NULL DEFAULT 2 COMMENT '库存状态：1、死货，2、非死货',
