-- ----------------------------
-- Table structure for power
-- ----------------------------
DROP TABLE IF EXISTS `power`;
CREATE TABLE `power`  (
  `id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '权限编号',
  `pid` int(10) UNSIGNED NOT NULL DEFAULT 0 COMMENT '所属权限编号，0 为顶级权限',
  `power_name` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '权限名称',
  `power_ico` varchar(150) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '权限图标',
  `power_url` varchar(150) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT 'power_url 权限访问路径，default = 默认',
  `rank` int(10) UNSIGNED NOT NULL DEFAULT 0 COMMENT '排序',
  `status` enum('免费','内部','收费') CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '免费' COMMENT '权限状态，1 = 正常，2 = 关闭',
  `show_menu` enum('显示','不显示') CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT '显示' COMMENT '是否显示在菜单栏',
  `price` decimal(10, 3) NULL DEFAULT 0.000,
  `is_admin` tinyint(1) NOT NULL DEFAULT 1,
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = MyISAM AUTO_INCREMENT = 612 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '权限表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for price_tag_apply_process
-- ----------------------------
DROP TABLE IF EXISTS `price_tag_apply_process`;
CREATE TABLE `price_tag_apply_process`  (
  `id` int(11) NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `task_id` int(11) NOT NULL DEFAULT 0 COMMENT '价签申请任务ID',
  `approve_user_id` int(11) NOT NULL DEFAULT 0 COMMENT '审批人ID',
  `approve_user_name` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT '' COMMENT '审批人姓名',
  `approve_order` int(11) NOT NULL DEFAULT 0 COMMENT '审批顺序',
  `role` varchar(20) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT '审批人' COMMENT '角色：审批人、抄送人',
  `base` tinyint(1) NOT NULL DEFAULT 0 COMMENT '是否基础配置：0-否，1-是',
  `level` int(11) NOT NULL DEFAULT 0 COMMENT '审批级别',
  `emp_id` int(11) NOT NULL DEFAULT 0 COMMENT '员工ID',
  `wx` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT '' COMMENT '微信账号',
  `create_time` int(11) NOT NULL DEFAULT 0 COMMENT '创建时间',
  `update_time` int(11) NOT NULL DEFAULT 0 COMMENT '更新时间',
  `create_user_id` int(11) NOT NULL DEFAULT 0 COMMENT '创建人ID',
  `update_user_id` int(11) NOT NULL DEFAULT 0 COMMENT '更新人ID',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_task_id`(`task_id`) USING BTREE,
  INDEX `idx_approve_user_id`(`approve_user_id`) USING BTREE,
  INDEX `idx_approve_order`(`approve_order`) USING BTREE,
  INDEX `idx_role`(`role`) USING BTREE,
  INDEX `idx_base`(`base`) USING BTREE,
  INDEX `idx_level`(`level`) USING BTREE,
  INDEX `idx_emp_id`(`emp_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 9 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '价签申请审批流程配置表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for price_tag_apply_process_log
-- ----------------------------
DROP TABLE IF EXISTS `price_tag_apply_process_log`;
CREATE TABLE `price_tag_apply_process_log`  (
  `id` int(11) NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `task_id` int(11) NOT NULL DEFAULT 0 COMMENT '价签申请任务ID',
  `approve_user_id` int(11) NOT NULL DEFAULT 0 COMMENT '审批人ID',
  `approve_user_name` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT '' COMMENT '审批人姓名',
  `approve_time` int(11) NOT NULL DEFAULT 0 COMMENT '审批时间',
  `approve_status` tinyint(1) NOT NULL DEFAULT 0 COMMENT '审批状态：0-待审批，1-通过，2-驳回，3-转交',
  `approve_opinion` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT '' COMMENT '审批意见',
  `next_approve_user_id` int(11) NOT NULL DEFAULT 0 COMMENT '下一审批人ID',
  `next_approve_user_name` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT '' COMMENT '下一审批人姓名',
  `create_time` int(11) NOT NULL DEFAULT 0 COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_task_id`(`task_id`) USING BTREE,
  INDEX `idx_approve_user_id`(`approve_user_id`) USING BTREE,
  INDEX `idx_approve_time`(`approve_time`) USING BTREE,
  INDEX `idx_approve_status`(`approve_status`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '价签申请审批流程日志表' ROW_FORMAT = Dynamic;

-- ----------------------------
