  `emp_id` int(11) NOT NULL DEFAULT 0 COMMENT '提报人ID',
  `create_user` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT '' COMMENT '提报人姓名',
  `create_time` int(11) NOT NULL DEFAULT 0 COMMENT '提报时间',
  `estimated_time` int(11) NOT NULL DEFAULT 0 COMMENT '预计完成时间',
  `finish_time` int(11) NOT NULL DEFAULT 0 COMMENT '实际完成时间',
  `fee` decimal(10, 2) NULL DEFAULT NULL COMMENT '费用',
  `status` tinyint(1) NOT NULL DEFAULT 0 COMMENT '状态：0-草稿，1-待审核，2-待制作，3-完成',
  `process_status` tinyint(1) NOT NULL DEFAULT 0 COMMENT '审批状态：0-待提交，1-审批中，2-已通过，3-已驳回',
  `current_approver_id` int(11) NOT NULL DEFAULT 0 COMMENT '当前审批人ID',
  `next_approver_id` int(11) NOT NULL DEFAULT 0 COMMENT '下一审批人ID',
  `remark` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT '' COMMENT '备注',
  `update_user_id` int(11) NULL DEFAULT NULL COMMENT '更新人ID',
  `update_time` int(11) NULL DEFAULT NULL COMMENT '更新时间',
  `submit_time` int(11) NULL DEFAULT NULL COMMENT '提交时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_dept_id`(`dept_id`) USING BTREE,
  INDEX `idx_emp_id`(`emp_id`) USING BTREE,
  INDEX `idx_status`(`status`) USING BTREE,
  INDEX `idx_create_time`(`create_time`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 96 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '价签申请任务主表' ROW_FORMAT = Dynamic;

-- ----------------------------
