  INDEX `idx_process_status`(`process_status`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 152 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '价签申请审批流程日志表' ROW_FORMAT = Dynamic;

