  `assets_category_id` int(11) NOT NULL COMMENT '资产类别',
  `name` varchar(100) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '资产名称',
  `model_number` varchar(100) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '规格型号',
  `assets_unit` int(11) NULL DEFAULT NULL COMMENT '计量单位',
