-- ----------------------------
-- Table structure for procurement_tool_sales
-- ----------------------------
DROP TABLE IF EXISTS `procurement_tool_sales`;
CREATE TABLE `procurement_tool_sales`  (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `warehouse_id` int(11) NOT NULL COMMENT '现库位',
