  `current_account_name` varchar(100) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '往来单位全名',
  `dept_id` int(11) NULL DEFAULT NULL COMMENT '部门',
  `subject_id` int(11) NOT NULL COMMENT '收入科目',
  `pay_bank_id` int(11) NOT NULL COMMENT '收款银行',
  `amount` decimal(11, 2) NOT NULL COMMENT '收款金额',
  `create_date` date NOT NULL,
  `abstract` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '摘要',
  `status` tinyint(1) NOT NULL DEFAULT 1 COMMENT '状态：1、草稿，2、单据',
