  `hongchong_abstract` text CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL,
  `is_lejuan` int(1) NOT NULL DEFAULT 0,
  `zhizhi_flg` int(1) NULL DEFAULT 0,
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `purchase_fixed_assets_search_index`(`id`, `bill_sn`, `account_set`, `cash_flow_subject_id`, `current_account_id`, `dept_id`, `subject_id`, `pay_bank_id`, `fee_id`) USING BTREE
