  `tax_ratio_money` decimal(15, 4) NULL DEFAULT NULL COMMENT '税金',
  `money1` decimal(15, 4) NULL DEFAULT NULL COMMENT '税前金额',
  `ar_no` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL,
  `yujimonth` int(11) NULL DEFAULT NULL,
  `yujidate` date NULL DEFAULT NULL,
  `chuanhuo_count` int(11) NULL DEFAULT 0,
  `status1` int(2) NULL DEFAULT 1 COMMENT '1有主 绑定订单 2无主 3店样',
  `is_import` tinyint(1) UNSIGNED NULL DEFAULT NULL COMMENT '导入到货明细',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 117187 CHARACTER SET = utf8 COLLATE = utf8_general_ci ROW_FORMAT = Dynamic;

