-- ----------------------------
-- Table structure for receipt
-- ----------------------------
DROP TABLE IF EXISTS `receipt`;
CREATE TABLE `receipt`  (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `company_id` int(11) NOT NULL,
  `receipt_no` varchar(100) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '编号',
  `customer_current_account_id` int(11) NULL DEFAULT NULL,
  `dept_id` int(11) NOT NULL COMMENT '收款人',
  `customer_id` int(11) NOT NULL COMMENT '付款人',
  `type` enum('其它','订单收款','意向金') CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '订单收款',
  `money` decimal(8, 2) NOT NULL COMMENT '收款金额',
  `forecast` decimal(8, 2) NULL DEFAULT NULL,
  `centent` text CHARACTER SET utf8 COLLATE utf8_general_ci NULL COMMENT '收款内容',
  `cash` decimal(8, 2) NULL DEFAULT NULL,
  `cade` decimal(8, 2) NULL DEFAULT NULL,
  `qrcode` decimal(8, 2) NULL DEFAULT NULL COMMENT '二维码',
  `transfer` decimal(8, 2) NULL DEFAULT NULL,
  `cheque` decimal(8, 2) NULL DEFAULT NULL,
  `market` decimal(8, 2) NULL DEFAULT NULL,
  `orders` decimal(8, 2) NULL DEFAULT NULL,
  `transfer_no` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL,
  `used` tinyint(3) NULL DEFAULT NULL,
  `create_date` date NULL DEFAULT NULL,
  `create_user` int(11) NULL DEFAULT NULL,
  `is_del` tinyint(3) NOT NULL DEFAULT 0 COMMENT '删除标记',
  `factory` decimal(8, 2) NULL DEFAULT NULL COMMENT '工厂代收',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 52365 CHARACTER SET = utf8 COLLATE = utf8_general_ci ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for receipt_order
-- ----------------------------
DROP TABLE IF EXISTS `receipt_order`;
CREATE TABLE `receipt_order`  (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `bill_sn` varchar(100) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL,
  `account_set` int(11) NULL DEFAULT NULL COMMENT '账套：1、大连，2、沈阳，3、石家庄',
