-- ----------------------------
-- Table structure for subjects
-- ----------------------------
DROP TABLE IF EXISTS `subjects`;
CREATE TABLE `subjects`  (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `category_id` int(11) NULL DEFAULT NULL COMMENT '分类ID',
  `category` tinyint(1) NOT NULL DEFAULT 1 COMMENT '科目类别:1、会计科目，2、支付方式',
  `pid` int(11) NOT NULL COMMENT '父ID',
  `code` varchar(100) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '科目编号',
  `name` varchar(100) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '科目全名',
  `debit` tinyint(1) NOT NULL DEFAULT 0 COMMENT '借方',
  `credit` tinyint(1) NOT NULL DEFAULT 0 COMMENT '贷方',
  `remark` text CHARACTER SET utf8 COLLATE utf8_general_ci NULL COMMENT '备注',
  `system_flg` tinyint(1) NULL DEFAULT 0 COMMENT '系统状态',
  `create_user_id` int(11) NULL DEFAULT NULL COMMENT '创建者',
  `create_time` int(10) NULL DEFAULT NULL COMMENT '创建时间',
  `update_user_id` int(11) NULL DEFAULT NULL COMMENT '更新者',
  `update_time` int(10) NULL DEFAULT NULL COMMENT '更新时间',
  `account_set` int(10) NULL DEFAULT NULL COMMENT '所属账套',
  `sort` int(11) NOT NULL DEFAULT 0,
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `subjects_search_index`(`id`, `category_id`, `pid`, `code`, `name`, `account_set`) USING BTREE
