CREATE TABLE `the_armory_application`  (
  `id` int(11) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '广宣费报销ID',
  `bill_sn` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '审批编号',
  `dept_id` int(11) NOT NULL COMMENT '创建人部门',
  `process_status` tinyint(1) NOT NULL COMMENT '审核状态：0未提交，1未审批，2审批通过，3已撤消，4审批拒绝',
  `create_time` int(10) NULL DEFAULT NULL COMMENT '创建时间',
  `create_user_id` int(11) NULL DEFAULT NULL COMMENT '创建人',
  `update_time` int(11) NULL DEFAULT NULL COMMENT '更新时间',
  `update_user_id` int(11) NULL DEFAULT NULL COMMENT '更新人',
  `copy` tinyint(1) NULL DEFAULT 0 COMMENT '是否是复制而来的单据0否 1是',
  `abstract` text CHARACTER SET utf8 COLLATE utf8_general_ci NULL,
  `approve_date` varchar(100) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL,
  `team_name` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL,
  `team_words` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL,
  `team_leader` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL,
  `team_emp` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL,
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 178 CHARACTER SET = utf8 COLLATE = utf8_general_ci ROW_FORMAT = Dynamic;

