-- ----------------------------
-- Table structure for transfer
-- ----------------------------
DROP TABLE IF EXISTS `transfer`;
CREATE TABLE `transfer`  (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `order_no` varchar(100) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '单号',
  `type` tinyint(1) NOT NULL DEFAULT 1 COMMENT '类型：1:采购部，2:店面',
  `from_warehouse_id` int(11) NOT NULL COMMENT '发货仓库',
  `to_warehouse_id` int(11) NOT NULL COMMENT '收货仓库',
  `expect_done_time` int(10) NULL DEFAULT NULL COMMENT '预计完成时间',
  `actual_done_time` int(10) NULL DEFAULT NULL COMMENT '实际完成时间',
  `cost_price` decimal(35, 20) NULL DEFAULT NULL COMMENT '成本',
  `status` tinyint(1) NULL DEFAULT NULL COMMENT '状态：1、准备中，2、出库，3，完结',
  `step` tinyint(1) NULL DEFAULT 4 COMMENT '审核阶段',
  `remark` text CHARACTER SET utf8 COLLATE utf8_general_ci NULL COMMENT '备注',
  `abstract` text CHARACTER SET utf8 COLLATE utf8_general_ci NULL COMMENT '摘要',
  `create_user_id` int(11) NULL DEFAULT NULL COMMENT '创建者',
  `create_time` int(10) NULL DEFAULT NULL COMMENT '创建时间',
  `update_user_id` int(11) NULL DEFAULT NULL COMMENT '更新者',
  `update_time` int(10) NULL DEFAULT NULL COMMENT '更新时间',
  `qzphoto` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '签字照片',
  `is_hongchong` int(2) NULL DEFAULT 0 COMMENT '是否开启红冲功能0：否    1：是',
  `no_to_do_remark` text CHARACTER SET utf8 COLLATE utf8_general_ci NULL COMMENT '不执行原因',
  `is_gjp_in` int(2) NULL DEFAULT NULL COMMENT '是否录入管家婆系统0：否  1是',
  `is_monthly` int(2) NULL DEFAULT 0 COMMENT '月结标志0：未月结  1：以月结',
  `is_del` int(2) NULL DEFAULT 0 COMMENT '是否删除标志0：否 1：是',
  `from_emp_id` int(11) NOT NULL,
  `to_emp_id` int(11) NOT NULL,
  `from_emp_flg` int(1) NOT NULL,
  `to_emp_flg` int(1) NOT NULL,
  `out_remark` text CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL,
  `in_remark` text CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL,
  `quzong_abstract` text CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL,
  `quzong_status` int(11) NOT NULL COMMENT '1 提交审核，曲总审核中  2同意  3驳回',
  `hongchong_abstract` text CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL,
  `report_date` datetime NOT NULL,
  `is_report` int(2) NOT NULL DEFAULT 0,
  `remark1` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL,
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 13172 CHARACTER SET = utf8 COLLATE = utf8_general_ci ROW_FORMAT = Dynamic;

-- ----------------------------
