-- ----------------------------
-- Table structure for travelexpensefee
-- ----------------------------
DROP TABLE IF EXISTS `travelexpensefee`;
CREATE TABLE `travelexpensefee`  (
  `id` int(11) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '广宣费报销ID',
  `bill_sn` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '审批编号',
  `dept_id` int(11) NOT NULL COMMENT '创建人部门',
  `total_money` decimal(11, 2) NOT NULL COMMENT '总金额',
  `cash_out` decimal(11, 2) NOT NULL COMMENT '已请款',
  `refund` decimal(11, 2) NOT NULL COMMENT '多退少补（自动计算：总金额-已请款）',
  `payee` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '收款单位/人',
  `bank` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '开户银行',
  `bank_account` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '银行账号',
  `attach_count` int(11) NOT NULL COMMENT '附件数量（张）',
  `process_status` tinyint(1) NOT NULL COMMENT '审核状态：0未提交，1未审批，2审批通过，3已撤消，4审批拒绝',
  `create_time` int(10) NULL DEFAULT NULL COMMENT '创建时间',
  `create_user_id` int(11) NULL DEFAULT NULL COMMENT '创建人',
  `update_time` int(11) NULL DEFAULT NULL COMMENT '更新时间',
  `update_user_id` int(11) NULL DEFAULT NULL COMMENT '更新人',
  `reason` text CHARACTER SET utf8 COLLATE utf8_general_ci NULL COMMENT '是由',
  `name_list` text CHARACTER SET utf8 COLLATE utf8_general_ci NULL COMMENT '人员名单',
  `population` int(11) NULL DEFAULT NULL COMMENT '出差人数',
  `departure` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '出发地',
  `arrival` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '目的地',
  `start_date` date NULL DEFAULT NULL COMMENT '开始时间',
  `end_date` date NULL DEFAULT NULL COMMENT '结束时间',
  `duration` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '时长',
  `copy` tinyint(1) NULL DEFAULT 0 COMMENT '是否是复制而来的单据0否 1是',
  `is_caiwu_flg` int(1) NOT NULL DEFAULT 0,
  `zhizhi_flg` int(1) NOT NULL DEFAULT 0,
  `is_chuna_flg` int(11) NOT NULL DEFAULT 0,
  `caiwu_remark` text CHARACTER SET utf8 COLLATE utf8_general_ci NULL,
  `now_approve_emp_id` int(10) NULL DEFAULT NULL,
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 470 CHARACTER SET = utf8 COLLATE = utf8_general_ci ROW_FORMAT = Dynamic;

