  `dingdanhao` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL,
  `is_idea` int(1) NOT NULL DEFAULT 0,
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 46575 CHARACTER SET = utf8 COLLATE = utf8_general_ci ROW_FORMAT = Dynamic;

