  `id` int(11) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '广宣费附件id',
  `pid` int(11) NOT NULL COMMENT '广宣费id',
  `attachment_name` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '附件名',
  `attachment_path` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '附件路径',
  `create_time` int(10) NULL DEFAULT NULL COMMENT '创建时间',
  `create_user_id` int(11) NULL DEFAULT NULL COMMENT '创建人',
  `update_time` int(10) NULL DEFAULT NULL COMMENT '更新时间',
  `update_user_id` int(11) NULL DEFAULT NULL COMMENT '更新人',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 99 CHARACTER SET = utf8 COLLATE = utf8_general_ci ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for wx_dept_manage_list
-- ----------------------------
DROP TABLE IF EXISTS `wx_dept_manage_list`;
CREATE TABLE `wx_dept_manage_list`  (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `dept_name` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL,
  `phone` varchar(100) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL,
  `address` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL,
  `dept_id` int(11) NULL DEFAULT NULL,
  `shop_image` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL,
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 5 CHARACTER SET = utf8 COLLATE = utf8_general_ci ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for wx_index_manage_attachment
-- ----------------------------
DROP TABLE IF EXISTS `wx_index_manage_attachment`;
CREATE TABLE `wx_index_manage_attachment`  (
  `id` int(11) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '广宣费附件id',
  `pid` int(11) NOT NULL COMMENT '广宣费id',
  `attachment_name` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '附件名',
  `attachment_path` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '附件路径',
  `create_time` int(10) NULL DEFAULT NULL COMMENT '创建时间',
  `create_user_id` int(11) NULL DEFAULT NULL COMMENT '创建人',
  `update_time` int(10) NULL DEFAULT NULL COMMENT '更新时间',
  `update_user_id` int(11) NULL DEFAULT NULL COMMENT '更新人',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 21 CHARACTER SET = utf8 COLLATE = utf8_general_ci ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for wx_index_manage_list
-- ----------------------------
DROP TABLE IF EXISTS `wx_index_manage_list`;
CREATE TABLE `wx_index_manage_list`  (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `name` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL,
  `type` int(2) NULL DEFAULT 0,
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 7 CHARACTER SET = utf8 COLLATE = utf8_general_ci ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for wxapp
-- ----------------------------
DROP TABLE IF EXISTS `wxapp`;
CREATE TABLE `wxapp`  (
  `wxapp_id` int(11) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '小程序id',
  `app_id` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '小程序AppID',
  `app_secret` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '小程序AppSecret',
  `mchid` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '微信商户号id',
  `apikey` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '微信支付密钥',
  `cert_pem` longtext CHARACTER SET utf8 COLLATE utf8_general_ci NULL COMMENT '证书文件cert',
  `key_pem` longtext CHARACTER SET utf8 COLLATE utf8_general_ci NULL COMMENT '证书文件key',
  `is_recycle` tinyint(3) UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否回收',
  `is_delete` tinyint(3) UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否删除',
  `create_time` int(11) UNSIGNED NOT NULL DEFAULT 0 COMMENT '创建时间',
  `update_time` int(11) UNSIGNED NOT NULL DEFAULT 0 COMMENT '更新时间',
  `background_image` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '',
  PRIMARY KEY (`wxapp_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 4 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '微信小程序记录表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for wxapp_category
-- ----------------------------
DROP TABLE IF EXISTS `wxapp_category`;
CREATE TABLE `wxapp_category`  (
  `category_id` int(11) UNSIGNED NOT NULL DEFAULT 0 COMMENT '小程序id',
  `category_style` tinyint(3) UNSIGNED NOT NULL DEFAULT 10 COMMENT '分类页样式(10一级分类[大图] 11一级分类[小图] 20二级分类)',
  `share_title` varchar(100) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '分享标题',
  `create_time` int(11) UNSIGNED NOT NULL DEFAULT 0 COMMENT '创建时间',
  `update_time` int(11) UNSIGNED NOT NULL DEFAULT 0 COMMENT '更新时间',
  PRIMARY KEY (`category_id`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '微信小程序分类页模板' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for wxapp_dealer_capital
-- ----------------------------
DROP TABLE IF EXISTS `wxapp_dealer_capital`;
CREATE TABLE `wxapp_dealer_capital`  (
  `id` int(11) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `user_id` int(11) UNSIGNED NOT NULL DEFAULT 0 COMMENT '分销商用户id',
  `flow_type` tinyint(3) UNSIGNED NOT NULL DEFAULT 10 COMMENT '资金流动类型 (10佣金收入 20提现支出)',
  `money` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '金额',
  `describe` varchar(500) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '描述',
  `wxapp_id` int(11) UNSIGNED NOT NULL DEFAULT 0 COMMENT '小程序id',
  `create_time` int(11) UNSIGNED NOT NULL DEFAULT 0 COMMENT '创建时间',
  `update_time` int(11) UNSIGNED NOT NULL DEFAULT 0 COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '分销商资金明细表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for wxapp_goods_car
-- ----------------------------
DROP TABLE IF EXISTS `wxapp_goods_car`;
CREATE TABLE `wxapp_goods_car`  (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `goods_id` int(11) NOT NULL COMMENT '产品ID',
  `user_id` int(11) NOT NULL COMMENT '用户id',
  `goods_price` decimal(11, 2) NULL DEFAULT NULL,
  `curtom_money` decimal(11, 2) NULL DEFAULT NULL COMMENT '价格',
  `curtom_number` decimal(11, 3) NULL DEFAULT 0.000 COMMENT '数量',
  `reg_date` int(11) NULL DEFAULT NULL COMMENT '添加时间',
  `rebate` int(11) NULL DEFAULT 1 COMMENT '折扣',
  `type` tinyint(2) NULL DEFAULT 0 COMMENT '1 打拆 2 返利 3...',
  `emp_id` int(11) NULL DEFAULT NULL,
  `brand_id` int(11) NULL DEFAULT NULL COMMENT '牌品ID',
  `class` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '家具种类',
  `wxapp_id` int(11) NULL DEFAULT 1,
  `type1` int(11) NULL DEFAULT 0 COMMENT '1在途  2在库  3预定',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 105 CHARACTER SET = utf8 COLLATE = utf8_general_ci ROW_FORMAT = COMPACT;

-- ----------------------------
-- Table structure for wxapp_help
-- ----------------------------
DROP TABLE IF EXISTS `wxapp_help`;
CREATE TABLE `wxapp_help`  (
  `id` int(11) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `title` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '帮助标题',
  `content` text CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '帮助内容',
  `sort` int(11) UNSIGNED NOT NULL DEFAULT 0 COMMENT '排序(数字越小越靠前)',
  `wxapp_id` int(11) UNSIGNED NOT NULL DEFAULT 0 COMMENT '小程序id',
  `create_time` int(11) UNSIGNED NOT NULL DEFAULT 0 COMMENT '创建时间',
  `update_time` int(11) UNSIGNED NOT NULL DEFAULT 0 COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '微信小程序帮助' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for wxapp_printer
-- ----------------------------
DROP TABLE IF EXISTS `wxapp_printer`;
CREATE TABLE `wxapp_printer`  (
  `printer_id` int(11) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '打印机id',
  `printer_name` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '打印机名称',
  `printer_type` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '打印机类型',
  `printer_config` text CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '打印机配置',
  `print_times` smallint(6) UNSIGNED NOT NULL DEFAULT 0 COMMENT '打印联数(次数)',
  `sort` int(11) UNSIGNED NOT NULL DEFAULT 0 COMMENT '排序 (数字越小越靠前)',
  `is_delete` int(11) UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否删除',
  `wxapp_id` int(11) UNSIGNED NOT NULL DEFAULT 0 COMMENT '小程序id',
  `create_time` int(11) UNSIGNED NOT NULL DEFAULT 0 COMMENT '创建时间',
  `update_time` int(11) UNSIGNED NOT NULL DEFAULT 0 COMMENT '更新时间',
  PRIMARY KEY (`printer_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '小票打印机记录表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for wxapp_region
-- ----------------------------
DROP TABLE IF EXISTS `wxapp_region`;
CREATE TABLE `wxapp_region`  (
  `id` int(11) NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `pid` int(11) NULL DEFAULT NULL COMMENT '父id',
  `shortname` varchar(100) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '简称',
  `name` varchar(100) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '名称',
  `merger_name` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '全称',
  `level` tinyint(4) UNSIGNED NULL DEFAULT 0 COMMENT '层级 1 2 3 省市区县',
  `pinyin` varchar(100) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '拼音',
  `code` varchar(100) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '长途区号',
  `zip_code` varchar(100) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '邮编',
  `first` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '首字母',
  `lng` varchar(100) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '经度',
  `lat` varchar(100) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '纬度',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `name,level`(`name`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 4019 CHARACTER SET = utf8 COLLATE = utf8_general_ci ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for wxapp_return_address
-- ----------------------------
DROP TABLE IF EXISTS `wxapp_return_address`;
CREATE TABLE `wxapp_return_address`  (
  `address_id` int(11) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '退货地址id',
  `name` varchar(30) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '收货人姓名',
  `phone` varchar(20) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '联系电话',
  `detail` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '详细地址',
  `sort` int(11) UNSIGNED NOT NULL DEFAULT 0 COMMENT '排序 (数字越小越靠前)',
  `is_delete` tinyint(3) UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否删除',
  `wxapp_id` int(11) UNSIGNED NOT NULL DEFAULT 0 COMMENT '小程序id',
  `create_time` int(11) UNSIGNED NOT NULL DEFAULT 0 COMMENT '创建时间',
  `update_time` int(11) UNSIGNED NOT NULL DEFAULT 0 COMMENT '更新时间',
  PRIMARY KEY (`address_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '退货地址记录表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for wxapp_setting
-- ----------------------------
DROP TABLE IF EXISTS `wxapp_setting`;
CREATE TABLE `wxapp_setting`  (
  `key` varchar(30) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '设置项标示',
  `describe` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '设置项描述',
  `values` mediumtext CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '设置内容（json格式）',
  `wxapp_id` int(11) UNSIGNED NOT NULL DEFAULT 0 COMMENT '小程序id',
  `update_time` int(11) UNSIGNED NOT NULL DEFAULT 0 COMMENT '更新时间',
  UNIQUE INDEX `unique_key`(`key`, `wxapp_id`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '小程序设置记录表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for wxapp_upload_file
-- ----------------------------
DROP TABLE IF EXISTS `wxapp_upload_file`;
CREATE TABLE `wxapp_upload_file`  (
  `id` int(11) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '文件id',
  `storage` varchar(20) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '存储方式',
  `group_id` int(11) UNSIGNED NOT NULL DEFAULT 0 COMMENT '文件分组id',
  `file_url` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '存储域名',
  `file_name` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '文件路径',
  `file_size` int(11) UNSIGNED NOT NULL DEFAULT 0 COMMENT '文件大小(字节)',
  `file_type` varchar(20) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '文件类型',
  `extension` varchar(20) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '文件扩展名',
  `is_user` int(11) UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否为c端用户上传',
  `is_recycle` tinyint(3) UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否已回收',
  `is_delete` tinyint(3) UNSIGNED NOT NULL DEFAULT 0 COMMENT '软删除',
  `wxapp_id` int(11) UNSIGNED NOT NULL DEFAULT 0 COMMENT '小程序id',
  `create_time` int(11) UNSIGNED NOT NULL DEFAULT 0 COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '文件库记录表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for wxapp_upload_group
-- ----------------------------
DROP TABLE IF EXISTS `wxapp_upload_group`;
CREATE TABLE `wxapp_upload_group`  (
  `id` int(11) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '分类id',
  `group_type` varchar(10) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '文件类型',
  `group_name` varchar(30) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '分类名称',
  `sort` int(11) UNSIGNED NOT NULL DEFAULT 0 COMMENT '分类排序(数字越小越靠前)',
  `is_delete` tinyint(3) UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否删除',
  `wxapp_id` int(11) UNSIGNED NOT NULL DEFAULT 0 COMMENT '小程序id',
  `create_time` int(11) UNSIGNED NOT NULL DEFAULT 0 COMMENT '创建时间',
  `update_time` int(11) UNSIGNED NOT NULL DEFAULT 0 COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '文件库分组记录表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for wxapp_user
-- ----------------------------
DROP TABLE IF EXISTS `wxapp_user`;
CREATE TABLE `wxapp_user`  (
  `user_id` int(11) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '用户id',
  `open_id` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '微信openid(唯一标示)',
  `phoneNumber` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '微信绑定电话',
  `address_id` int(11) UNSIGNED NOT NULL DEFAULT 0 COMMENT '默认收货地址',
  `balance` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '用户可用余额',
  `points` int(11) UNSIGNED NOT NULL DEFAULT 0 COMMENT '用户可用积分',
  `pay_money` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '用户总支付的金额',
  `expend_money` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '实际消费的金额(不含退款)',
  `grade_id` int(11) UNSIGNED NOT NULL DEFAULT 0 COMMENT '会员等级id',
  `is_delete` tinyint(3) UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否删除',
  `wxapp_id` int(11) UNSIGNED NOT NULL DEFAULT 0 COMMENT '小程序id',
  `create_time` int(11) UNSIGNED NOT NULL DEFAULT 0 COMMENT '创建时间',
  `update_time` int(11) UNSIGNED NOT NULL DEFAULT 0 COMMENT '更新时间',
  `invoice_id` int(11) UNSIGNED NOT NULL DEFAULT 0 COMMENT '默认发票',
  `birthday` date NULL DEFAULT NULL,
  `nick_name` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL,
  `sex` enum('男','女') CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT '男',
  PRIMARY KEY (`user_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 205 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '微信小程序用户记录表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for wxapp_user_address
-- ----------------------------
DROP TABLE IF EXISTS `wxapp_user_address`;
CREATE TABLE `wxapp_user_address`  (
  `address_id` int(11) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `name` varchar(30) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '收货人姓名',
  `phone` varchar(20) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '联系电话',
  `province_id` int(11) UNSIGNED NOT NULL DEFAULT 0 COMMENT '所在省份id',
  `city_id` int(11) UNSIGNED NOT NULL DEFAULT 0 COMMENT '所在城市id',
  `region_id` int(11) UNSIGNED NOT NULL DEFAULT 0 COMMENT '所在区id',
  `district` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT '' COMMENT '新市辖区(该字段用于记录region表中没有的市辖区)',
  `detail` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '详细地址',
  `user_id` int(11) UNSIGNED NOT NULL DEFAULT 0 COMMENT '用户id',
  `wxapp_id` int(11) UNSIGNED NOT NULL DEFAULT 0 COMMENT '小程序id',
  `create_time` int(11) UNSIGNED NOT NULL DEFAULT 0 COMMENT '创建时间',
  `update_time` int(11) UNSIGNED NOT NULL DEFAULT 0 COMMENT '更新时间',
  PRIMARY KEY (`address_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 10 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '用户收货地址表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for wxapp_user_balance_log
-- ----------------------------
DROP TABLE IF EXISTS `wxapp_user_balance_log`;
CREATE TABLE `wxapp_user_balance_log`  (
  `id` int(11) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `user_id` int(11) UNSIGNED NOT NULL DEFAULT 0 COMMENT '用户id',
  `scene` tinyint(3) UNSIGNED NOT NULL DEFAULT 10 COMMENT '余额变动场景(10用户充值 20用户消费 30管理员操作 40订单退款)',
  `money` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '变动金额',
  `describe` varchar(500) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '描述/说明',
  `remark` varchar(500) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '管理员备注',
  `wxapp_id` int(11) UNSIGNED NOT NULL DEFAULT 0 COMMENT '小程序商城id',
  `create_time` int(11) UNSIGNED NOT NULL DEFAULT 0 COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '用户余额变动明细表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for wxapp_user_coupon
-- ----------------------------
DROP TABLE IF EXISTS `wxapp_user_coupon`;
CREATE TABLE `wxapp_user_coupon`  (
  `id` int(11) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `coupon_id` int(11) UNSIGNED NOT NULL COMMENT '优惠券id',
  `name` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '优惠券名称',
  `color` tinyint(3) UNSIGNED NOT NULL DEFAULT 10 COMMENT '优惠券颜色(10蓝 20红 30紫 40黄)',
  `coupon_type` tinyint(3) UNSIGNED NOT NULL DEFAULT 10 COMMENT '优惠券类型(10满减券 20折扣券)',
  `reduce_price` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '满减券-减免金额',
  `discount` tinyint(3) UNSIGNED NOT NULL DEFAULT 0 COMMENT '折扣券-折扣率(0-100)',
  `min_price` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '最低消费金额',
  `expire_type` tinyint(3) UNSIGNED NOT NULL DEFAULT 10 COMMENT '到期类型(10领取后生效 20固定时间)',
  `expire_day` int(11) UNSIGNED NOT NULL DEFAULT 0 COMMENT '领取后生效-有效天数',
  `start_time` int(11) UNSIGNED NOT NULL DEFAULT 0 COMMENT '有效期开始时间',
  `end_time` int(11) UNSIGNED NOT NULL DEFAULT 0 COMMENT '有效期结束时间',
  `apply_range` tinyint(3) UNSIGNED NOT NULL DEFAULT 10 COMMENT '适用范围(10全部商品 20指定商品 30排除商品)',
  `apply_range_config` text CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '适用范围配置(json格式)',
  `is_expire` tinyint(3) UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否过期(0未过期 1已过期)',
  `is_use` tinyint(3) UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否已使用(0未使用 1已使用)',
  `user_id` int(11) UNSIGNED NOT NULL DEFAULT 0 COMMENT '用户id',
  `wxapp_id` int(11) UNSIGNED NOT NULL DEFAULT 0 COMMENT '小程序id',
  `create_time` int(11) UNSIGNED NOT NULL DEFAULT 0 COMMENT '创建时间',
  `update_time` int(11) UNSIGNED NOT NULL DEFAULT 0 COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '用户优惠券记录表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for wxapp_user_grade
-- ----------------------------
DROP TABLE IF EXISTS `wxapp_user_grade`;
CREATE TABLE `wxapp_user_grade`  (
  `id` int(11) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '等级ID',
  `name` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '等级名称',
  `weight` int(11) UNSIGNED NOT NULL DEFAULT 1 COMMENT '等级权重(1-9999)',
  `upgrade` text CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '升级条件',
  `equity` text CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '等级权益(折扣率0-100)',
  `status` tinyint(3) UNSIGNED NOT NULL DEFAULT 1 COMMENT '状态(1启用 0禁用)',
  `is_delete` tinyint(3) UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否删除',
  `wxapp_id` int(11) UNSIGNED NOT NULL DEFAULT 0 COMMENT '小程序id',
  `create_time` int(11) UNSIGNED NOT NULL DEFAULT 0 COMMENT '创建时间',
  `update_time` int(11) UNSIGNED NOT NULL DEFAULT 0 COMMENT '更新时间',
  `min` int(11) NULL DEFAULT NULL COMMENT '等级区间 下限',
  `max` int(11) NULL DEFAULT NULL COMMENT '等级区间 上限',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 5 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '用户会员等级表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for wxapp_user_grade_log
-- ----------------------------
DROP TABLE IF EXISTS `wxapp_user_grade_log`;
CREATE TABLE `wxapp_user_grade_log`  (
  `id` int(11) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `user_id` int(11) UNSIGNED NOT NULL DEFAULT 0 COMMENT '用户id',
  `old_grade_id` int(11) UNSIGNED NOT NULL DEFAULT 0 COMMENT '变更前的等级id',
  `new_grade_id` int(11) UNSIGNED NOT NULL DEFAULT 0 COMMENT '变更后的等级id',
  `change_type` tinyint(3) UNSIGNED NOT NULL DEFAULT 10 COMMENT '变更类型(10后台管理员设置 20自动升级)',
  `remark` varchar(500) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT '' COMMENT '管理员备注',
  `wxapp_id` int(11) UNSIGNED NOT NULL DEFAULT 0 COMMENT '小程序id',
  `create_time` int(11) UNSIGNED NOT NULL DEFAULT 0 COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '用户会员等级变更记录表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for wxapp_user_invoice
-- ----------------------------
DROP TABLE IF EXISTS `wxapp_user_invoice`;
CREATE TABLE `wxapp_user_invoice`  (
  `invoice_id` int(11) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `type` int(2) NOT NULL DEFAULT 1 COMMENT '类型，1个人  2公司',
  `name` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '名称',
  `duty_paragraph` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT '' COMMENT '税号',
  `adress` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT '' COMMENT '地址',
  `phone` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT '' COMMENT '电话',
  `bank_name` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT '' COMMENT '开户银行',
  `bank_no` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT '' COMMENT '银行账号',
  `user_id` int(11) UNSIGNED NOT NULL DEFAULT 0 COMMENT '用户id',
  `wxapp_id` int(11) UNSIGNED NOT NULL DEFAULT 0 COMMENT '小程序id',
  `create_time` int(11) UNSIGNED NOT NULL DEFAULT 0 COMMENT '创建时间',
  `update_time` int(11) UNSIGNED NOT NULL DEFAULT 0 COMMENT '更新时间',
  PRIMARY KEY (`invoice_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '用户收货地址表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for wxapp_user_points_log
-- ----------------------------
DROP TABLE IF EXISTS `wxapp_user_points_log`;
CREATE TABLE `wxapp_user_points_log`  (
  `id` int(11) NOT NULL COMMENT '主键id',
  `user_id` int(11) UNSIGNED NOT NULL DEFAULT 0 COMMENT '用户id',
  `value` int(11) NOT NULL DEFAULT 0 COMMENT '变动数量',
  `describe` varchar(500) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '描述/说明',
  `remark` varchar(500) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '管理员备注',
  `wxapp_id` int(11) UNSIGNED NOT NULL DEFAULT 0 COMMENT '小程序id',
  `create_time` int(11) UNSIGNED NOT NULL DEFAULT 0 COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '用户积分变动明细表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for yearly_balance
-- ----------------------------
DROP TABLE IF EXISTS `yearly_balance`;
CREATE TABLE `yearly_balance`  (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `yearly_date` date NULL DEFAULT NULL COMMENT '月份',
  `account_set` int(11) NULL DEFAULT NULL COMMENT '账套：50、大连，16、沈阳，89、石家庄,101、石家庄,107、唐愫',
  `create_user_id` int(11) NULL DEFAULT NULL COMMENT '创建人',
  `create_time` int(11) NULL DEFAULT NULL COMMENT '创建时间',
  `update_user_id` int(11) NULL DEFAULT NULL COMMENT '更新人',
  `update_time` int(11) NULL DEFAULT NULL COMMENT '更新时间',
  `is_back_yearly` int(2) NULL DEFAULT 0 COMMENT '是否可以反月结0：是  1：否',
  `is_del` int(2) NULL DEFAULT 0 COMMENT '是否删除0:否   1：是',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `yearly_balance_search_index`(`id`, `yearly_date`, `account_set`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 189 CHARACTER SET = utf8 COLLATE = utf8_general_ci ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for yichang_uptowarehouse
-- ----------------------------
DROP TABLE IF EXISTS `yichang_uptowarehouse`;
CREATE TABLE `yichang_uptowarehouse`  (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `goods_id` int(11) NULL DEFAULT NULL COMMENT '产品ID',
  `yichangShouhou_memo` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '异常售后备注',
  `yichang_status` int(11) NULL DEFAULT NULL COMMENT '1 已提交\r\n2 处理中\r\n3 处理完毕',
  `yichang_date` int(11) NULL DEFAULT NULL COMMENT '异常处理时间',
  `user_id` int(11) NULL DEFAULT NULL COMMENT '操作人id',
  `user_name` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '操作人name',
  `uwid` int(11) NULL DEFAULT NULL COMMENT '上报入库单id',
  `yichangGoods_no` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '产品型号',
  `yichangGoods_name` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '产品名称',
  `yichang_kuwei` int(11) NULL DEFAULT NULL COMMENT '库位',
  `yichang_volume` int(11) NOT NULL DEFAULT 0 COMMENT '异常数量',
  `yichang_unit_quantity` int(11) NULL DEFAULT NULL COMMENT '件数',
  `yichang_unit` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '单位',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8 COLLATE = utf8_general_ci ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for yiyelianmeng
-- ----------------------------
DROP TABLE IF EXISTS `yiyelianmeng`;
CREATE TABLE `yiyelianmeng`  (
  `id` bigint(20) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '异业联盟id',
  `user_id` bigint(20) NOT NULL COMMENT '用户ID',
  `desginer_name` varchar(100) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '异业联盟姓名',
  `desginer_mobile` varchar(20) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '异业联盟联系电话',
  `desginer_company` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '异业联盟公司',
  `business_card` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT '' COMMENT '异业联盟名片',
  `photo` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT '' COMMENT '异业联盟照片',
  `desginer_address` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT '' COMMENT '异业联盟办公地址',
  `bank` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT '' COMMENT '开户银行',
  `bank_code` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '银行卡号',
  `create_time` int(10) NOT NULL DEFAULT 0 COMMENT '创建时间',
  `create_user_id` bigint(20) NOT NULL COMMENT '创建人',
  `desginer_property` int(11) NULL DEFAULT NULL COMMENT '异业联盟属性:内部，外部',
  `old_desginer_id` int(11) NULL DEFAULT NULL COMMENT '旧异业联盟ID',
  `jieshiqudao` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '结识渠道',
  `quexiangreason` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '缺项理由',
  `jieshidate` date NULL DEFAULT NULL COMMENT '结识时间',
  `zhiwu` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL,
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 825 CHARACTER SET = utf8 COLLATE = utf8_general_ci ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for yiyelianmeng_customer_shenhe
-- ----------------------------
DROP TABLE IF EXISTS `yiyelianmeng_customer_shenhe`;
CREATE TABLE `yiyelianmeng_customer_shenhe`  (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `desginer_id` int(11) NULL DEFAULT NULL COMMENT '异业联盟id',
  `create_user_id` int(11) NULL DEFAULT NULL COMMENT '创建者id',
  `customer_id` int(11) NULL DEFAULT NULL COMMENT '客户id',
  `shenheren_id` int(11) NULL DEFAULT NULL COMMENT '审核人',
  `shenheren_name` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '审核人name',
  `shenhe_time` int(11) NULL DEFAULT NULL COMMENT '审核时间',
  `shenhe_status` int(11) NULL DEFAULT NULL COMMENT '审核状态：1通过2驳回',
  `bohui_reason` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '驳回理由',
  `weizhi` int(11) NULL DEFAULT NULL COMMENT '位置',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 784 CHARACTER SET = utf8 COLLATE = utf8_general_ci ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for yiyelianmeng_shenhe
-- ----------------------------
DROP TABLE IF EXISTS `yiyelianmeng_shenhe`;
CREATE TABLE `yiyelianmeng_shenhe`  (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `desginer_id` int(11) NULL DEFAULT NULL COMMENT '异业联盟id',
  `create_user_id` int(11) NULL DEFAULT NULL COMMENT '创建者id',
  `shenheren_id` int(11) NULL DEFAULT NULL COMMENT '审核人',
  `shenheren_name` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '审核人name',
  `shenhe_time` int(11) NULL DEFAULT NULL COMMENT '审核时间',
  `shenhe_status` int(11) NULL DEFAULT NULL COMMENT '审核状态：1通过2驳回',
  `bohui_reason` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '驳回理由',
  `weizhi` int(11) NULL DEFAULT NULL COMMENT '位置',
  `update_id` int(11) NULL DEFAULT NULL COMMENT '重新编辑的人id',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1499 CHARACTER SET = utf8 COLLATE = utf8_general_ci ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for yiyelianmeng_temp
-- ----------------------------
DROP TABLE IF EXISTS `yiyelianmeng_temp`;
CREATE TABLE `yiyelianmeng_temp`  (
  `id` bigint(20) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '设计师id',
  `desginer_name` varchar(100) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '设计师姓名',
  `desginer_mobile` varchar(20) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '设计师联系电话',
  `desginer_company` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '设计师公司',
  `business_card` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT '' COMMENT '设计师名片',
  `photo` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT '' COMMENT '设计师照片',
  `desginer_address` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT '' COMMENT '设计师办公地址',
  `bank` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT '' COMMENT '开户银行',
  `bank_code` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '银行卡号',
  `create_user_id` bigint(20) NOT NULL COMMENT '创建人',
  `desginer_property` int(11) NULL DEFAULT NULL COMMENT '设计师属性:内部，外部',
  `jieshiqudao` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '结识渠道',
  `desginer_id` int(11) NULL DEFAULT NULL COMMENT '设计师表id',
  `update_reason` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '修改原因',
