) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '整点秒杀-活动会场场次表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for yoshop_sharp_goods
-- ----------------------------
DROP TABLE IF EXISTS `yoshop_sharp_goods`;
