CREATE ALGORITHM = UNDEFINED SQL SECURITY DEFINER VIEW `inventory_info` AS select ifnull(`f`.`id`,'0') AS `factory_id`,ifnull(`f`.`name`,'无供应商信息') AS `factory_name`,`b`.`id` AS `id`,`g`.`brand_id` AS `brand_id`,`b`.`name` AS `brand_name`,`i`.`goods_id` AS `goods_id`,`g`.`goods_no` AS `goods_no`,`g`.`name` AS `goods_name`,`i`.`warehouse_id` AS `warehouse_id`,`w`.`dept_id` AS `dept_id`,`w`.`name` AS `warehouse_name`,`w`.`account_set` AS `account_set`,`i`.`purchase_item_id` AS `purchase_item_id`,`i`.`put_in_storage_item_id` AS `put_in_storage_item_id`,`i`.`transfer_item_id` AS `transfer_item_id`,`i`.`order_exchange_in_item_id` AS `order_exchange_in_item_id`,`i`.`order_exchange_out_item_id` AS `order_exchange_out_item_id`,`i`.`loss_reporting_item_id` AS `loss_reporting_item_id`,`i`.`excess_reporting_item_id` AS `excess_reporting_item_id`,`i`.`order_dismountin_in_item_id` AS `order_dismountin_in_item_id`,`i`.`order_dismountin_out_item_id` AS `order_dismountin_out_item_id`,if((`i`.`remark` <> '快销品开单'),`i`.`order_delivery_item_id`,NULL) AS `order_delivery_item_id`,if((`i`.`remark` <> '删除快销品'),`i`.`order_return_item_id`,NULL) AS `order_return_item_id`,if((`i`.`remark` = '快销品开单'),`i`.`order_delivery_item_id`,NULL) AS `orders_item_id`,if((`i`.`remark` = '删除快销品'),`i`.`order_return_item_id`,NULL) AS `orders_return_item_id`,`i`.`count` AS `count`,`i`.`cost_price` AS `cost_price`,`i`.`mwa` AS `mwa`,`i`.`remark` AS `remark`,date_format(from_unixtime(`i`.`create_date`),'%Y-%m-%d') AS `create_date`,`i`.`is_settlement` AS `is_settlement` from ((((`inventory` `i` join `goods` `g` on((`i`.`goods_id` = `g`.`id`))) left join `factory` `f` on((`g`.`factory_id` = `f`.`id`))) join `brand` `b` on((`g`.`brand_id` = `b`.`id`))) join `warehouse` `w` on((`i`.`warehouse_id` = `w`.`id`))) where (`i`.`is_settlement` = 1);

