DROP VIEW IF EXISTS `weiwanjiedingdanshangpinshuliang`;
CREATE ALGORITHM = UNDEFINED SQL SECURITY DEFINER VIEW `weiwanjiedingdanshangpinshuliang` AS select `g`.`id` AS `id`,sum(`oud`.`curtom_number`) AS `order_cnt` from ((`goods` `g` join `order_user_detail` `oud` on((`g`.`id` = `oud`.`goods_id`))) join `order_user` `ou` on((`oud`.`pid` = `ou`.`id`))) where ((`ou`.`type` = '1') and (`ou`.`status` >= '9') and (`ou`.`status` < '14')) group by `g`.`id`;

