DROP VIEW IF EXISTS `year_dept_sales_sub1`;
CREATE ALGORITHM = UNDEFINED SQL SECURITY DEFINER VIEW `year_dept_sales_sub1` AS select `d`.`id` AS `id`,`d`.`name` AS `name`,sum(`os`.`amount`) AS `amount`,ifnull(sum((`os`.`proportion` * `odf`.`designer_fee`)),0) AS `designer_fee` from (((`order_user` `ou` join `order_sales` `os` on((`ou`.`id` = `os`.`order_id`))) join `dept` `d` on((`os`.`dept_id` = `d`.`id`))) left join `order_design_fees` `odf` on(((`ou`.`id` = `odf`.`order_id`) and (`odf`.`status` = 10)))) where ((year(from_unixtime(`ou`.`reg_date`)) = year(now())) and (`d`.`type_en` = 'sales')) group by `d`.`id`;

