-- ----------------------------
-- Function structure for getParentDeptPids
-- ----------------------------
DROP FUNCTION IF EXISTS `getParentDeptPids`;
delimiter ;;
CREATE DEFINER=`root`@`localhost` FUNCTION `getParentDeptPids`(currentId varchar(100)) RETURNS varchar(1000) CHARSET utf8
BEGIN
DECLARE myPid VARCHAR(255) DEFAULT '';
DECLARE str VARCHAR(255) DEFAULT '';
WHILE (currentId IS NOT NULL OR currentId != '') DO
SET myPid = (SELECT group_concat(pid) FROM dept WHERE id=currentId and pid > 0);
IF myPid IS NOT NULL THEN
IF str !='' THEN
SET str=CONCAT(str,',',myPid);
ELSE
SET str=myPid;
END IF;
SET currentId=myPid;
ELSE
SET currentId=myPid;
END IF;
END WHILE;
RETURN str;
END
;;
delimiter ;

