-- ----------------------------
-- Procedure structure for ProfitStatement
-- ----------------------------
DROP PROCEDURE IF EXISTS `ProfitStatement`;
delimiter ;;
CREATE DEFINER=`root`@`localhost` PROCEDURE `ProfitStatement`(in account_set int)
BEGIN
	select id,subject_id,amount amount from general_cost_bill WHERE dept_id in (SELECT id FROM dept WHERE pid = account_set) and `status` = 2
	UNION ALL
	select id,subject_id,amount amount from current_cost WHERE dept_id in (SELECT id FROM dept WHERE pid = account_set) and `status` = 2
	UNION ALL
	select id,current_account_id subject_id,amount from receipt_order WHERE  dept_id in (SELECT id FROM dept WHERE pid = account_set) and `status` = 2 AND current_account_type = 8888
	UNION ALL
	select id,current_id subject_id,amount amount from payment_order WHERE  dept_id in (SELECT id FROM dept WHERE pid = account_set) and `status` = 2 AND current_type = 8888
	UNION ALL
	select id,subject_id,IF(debtor>0,debtor,-1*lender) amount from accounting_voucher where  dept_id in (SELECT id FROM dept WHERE pid = account_set) AND `status` = 2 AND current_account_type = '4'
	UNION ALL
	select id,subject_id,amount from current_other_income where  dept_id in (SELECT id FROM dept WHERE pid = account_set) AND `status` = 2
	UNION ALL
	select id,subject_id,amount from other_income where  dept_id in (SELECT id FROM dept WHERE pid = account_set) AND `status` = 2
	UNION ALL
	select id,168 subject_id,price amount from order_delivery WHERE  dept_id in (SELECT id FROM dept WHERE pid = account_set) AND `status` = 4
	UNION ALL
	select id,168 subject_id,price amount from order_return WHERE  dept_id in (SELECT id FROM dept WHERE pid = account_set) AND `status` = 4
	UNION ALL
	select i.id,185 subject_id,-1*count*mwa amount from inventory i JOIN warehouse w ON i.warehouse_id = w.id WHERE w.account_set in (SELECT id FROM warehouse WHERE account_set = account_set) AND (i.order_return_item_id >0 OR i.order_delivery_item_id >0)
	UNION ALL
	select i.id,276 subject_id,(-1*count*mwa) - (-1*count*purchase_cost_price) amount from inventory i JOIN warehouse w ON i.warehouse_id in (SELECT id FROM warehouse WHERE account_set = account_set) WHERE w.account_set in (warehouse_id) AND i.put_in_storage_item_id > 0 AND i.count < 0;	
END
;;
delimiter ;

SET FOREIGN_KEY_CHECKS = 1;
